-- 0100_jlpt_n1_batch_20261015_20261028.sql
-- Generated from validated project-authored source data. No remote query is run by this generator.
-- Scope is deliberately bounded to N1_2027_JUL / 2026-10-15..2026-10-28.
-- No plan-wide curriculum deletion, count scan, or legacy learning-data deletion occurs.

DROP TABLE IF EXISTS _n1_b2_guard_0100;
CREATE TABLE _n1_b2_guard_0100 (ok INTEGER NOT NULL CHECK (ok = 1));
DROP TABLE _n1_b2_guard_0100;

DROP TABLE IF EXISTS _n1_b2_words_0100;
CREATE TABLE _n1_b2_words_0100 (source_key TEXT PRIMARY KEY, study_date TEXT NOT NULL, word TEXT NOT NULL, reading TEXT NOT NULL, meaning_ko TEXT NOT NULL, meaning_ja TEXT NOT NULL, example_ja TEXT NOT NULL, example_ko TEXT NOT NULL);

DELETE FROM japanese_jlpt_daily_words WHERE session_id IN (SELECT s.id FROM japanese_jlpt_daily_sessions s JOIN japanese_jlpt_study_plans p ON p.id=s.plan_id WHERE p.plan_code='N1_2027_JUL' AND s.study_date BETWEEN '2026-10-15' AND '2026-10-28');
DELETE FROM japanese_jlpt_daily_contents WHERE plan_id IN (SELECT id FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL') AND study_date BETWEEN '2026-10-15' AND '2026-10-28';
DELETE FROM japanese_jlpt_daily_sessions WHERE plan_id IN (SELECT id FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL') AND study_date BETWEEN '2026-10-15' AND '2026-10-28';

DROP TABLE IF EXISTS _n1_b2_map_0100;
CREATE TABLE _n1_b2_map_0100 (source_key TEXT PRIMARY KEY, word_id INTEGER NOT NULL);
UPDATE japanese_words AS w SET meaning_ko=s.meaning_ko,meaning_ja=s.meaning_ja,ai_status='reviewed',updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') FROM _n1_b2_map_0100 m JOIN _n1_b2_words_0100 s ON s.source_key=m.source_key WHERE w.id=m.word_id;


DROP TABLE _n1_b2_map_0100;
DROP TABLE _n1_b2_words_0100;

