INSERT INTO _n1_b2_guard_0100(ok) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM japanese_jlpt_daily_sessions s JOIN japanese_jlpt_study_plans p ON p.id=s.plan_id WHERE p.plan_code='N1_2027_JUL' AND s.study_date BETWEEN '2026-10-15' AND '2026-10-28' AND (s.status <> 'not_started' OR s.started_at IS NOT NULL OR s.completed_at IS NOT NULL)) THEN 1 ELSE 0 END;
INSERT INTO _n1_b2_words_0100(source_key,study_date,word,reading,meaning_ko,meaning_ja,example_ja,example_ko) VALUES
('n1-0756','2026-10-15','対等','たいとう','대등함; 동등한 관계','地位・権利・能力などに上下や優劣がなく、同じ立場であるさま。','取引先とは上下関係ではなく、対等なパートナーとして協力したい。','거래처와는 상하관계가 아니라 대등한 파트너로 협력하고 싶다.'),
('n1-0900','2026-10-15','所定','しょてい','소정; 정해진 바','あらかじめ定められていること。また、その定められた場所・方法・条件。','申請書は所定の様式に記入し、期限までに提出してください。','신청서는 정해진 양식에 기입해 기한까지 제출해 주세요.'),
('n1-0941','2026-10-15','切実','せつじつ','절실함; 절박함','自分に深く関わり、非常に強く感じられるさま。必要性などが差し迫っているさま。','人手不足の解消は、地方の中小企業にとって切実な課題である。','인력 부족 해소는 지방 중소기업에 절실한 과제다.'),
('n1-1008','2026-10-15','有する','ゆうする','가지다; 보유하다','性質・能力・権利・資産などを持っている。','この資格を取得するには、一定期間の実務経験を有することが条件となる。','이 자격을 취득하려면 일정 기간의 실무 경험을 보유하는 것이 조건이다.'),
('n1-1014','2026-10-15','問う','とう','묻다; 따지다; 문제 삼다','答え・説明を求める。また、責任・価値・是非などを問題として取り上げる。','この試験では知識量だけでなく、情報を分析する力も問われる。','이 시험에서는 지식량뿐 아니라 정보를 분석하는 능력도 요구된다.'),
('n1-1060','2026-10-15','如何に','いかに','어떻게; 얼마나; 아무리 ~해도','方法・程度を問う硬い表現。また『いかに〜ても』で『どんなに〜ても』の意味を表す。','限られた予算を如何に有効に使うかが問われている。','한정된 예산을 어떻게 효과적으로 사용할지가 문제되고 있다.'),
('n1-1159','2026-10-15','反する','はんする','반하다; 어긋나다; 위반하다','方針・規則・期待・事実などと一致せず、反対の関係にある。','個人情報を無断で公開する行為は社内規定に反する。','개인정보를 무단으로 공개하는 행위는 사내 규정에 위반된다.'),
('n1-1181','2026-10-15','上回る','うわまわる','웃돌다; 상회하다','数値・程度・実績などが基準・比較対象より高くなる。','今年の売上は当初の予想を大きく上回った。','올해 매출은 당초 예상을 크게 웃돌았다.'),
('n1-1187','2026-10-15','費やす','ついやす','쓰다; 들이다','時間・労力・金銭などを、ある目的のために使う。','原因調査に多くの時間を費やしたが、根本的な問題を特定できた。','원인 조사에 많은 시간을 들였지만 근본적인 문제를 특정할 수 있었다.'),
('n1-1215','2026-10-15','受け継ぐ','うけつぐ','이어받다; 계승하다','前の世代・担当者などから、財産・伝統・技術・精神・仕事などを引き継ぐ。','若い職人が師匠から伝統的な技術を受け継いでいる。','젊은 장인이 스승에게서 전통 기술을 이어받고 있다.'),
('n1-1237','2026-10-15','辿る','たどる','더듬어 가다; 따라가다; 추적하다','道・経過・記憶・歴史などを順に追って進む。','記録を辿ると、問題は数か月前から少しずつ発生していた。','기록을 따라가 보면 문제는 몇 달 전부터 조금씩 발생하고 있었다.'),
('n1-1249','2026-10-15','簡易','かんい','간이; 간단한 방식','構造・手続き・設備などを必要最低限にして簡単にしたさま。','まず簡易版を公開し、利用状況を見ながら機能を追加する。','먼저 간이 버전을 공개하고 이용 상황을 보며 기능을 추가한다.'),
('n1-1256','2026-10-15','深める','ふかめる','깊게 하다; 심화하다','理解・関係・知識・交流などの程度をさらに深くする。','議論を重ねることで互いの理解を深めることができた。','논의를 거듭해 서로에 대한 이해를 깊게 할 수 있었다.'),
('n1-1263','2026-10-15','取り扱う','とりあつかう','취급하다; 다루다','物・情報・商品・問題などを対象として扱い、操作・販売・処理する。','この画面では個人情報を取り扱うため、権限管理が必要だ。','이 화면에서는 개인정보를 취급하므로 권한 관리가 필요하다.'),
('n1-1281','2026-10-15','引き上げる','ひきあげる','끌어올리다; 인상하다; 철수하다','物を上へ引き上げる。また、価格・水準・地位などを高くする。文脈によってはその場から引き払う意味にも用いる。','会社は来年度から基本給を段階的に引き上げる方針だ。','회사는 내년부터 기본급을 단계적으로 인상할 방침이다.'),
('n1-1322','2026-10-15','絡む','からむ','얽히다; 관련되다; 시비를 걸다','糸・物などが巻き付いて離れにくくなる。また、複数の事情・人間関係などが複雑に関係する。','この問題には法律と技術の両方が絡んでいる。','이 문제에는 법률과 기술 양쪽이 얽혀 있다.'),
('n1-1325','2026-10-15','いっそ','いっそ','차라리; 아예','中途半端な方法を選ぶより、思い切って別の方法を選ぶ方がよいという気持ちを表す。','修理費が高いなら、いっそ新しい機種に買い替えた方がいい。','수리비가 비싸다면 차라리 새 기종으로 바꾸는 편이 낫다.'),
('n1-1326','2026-10-15','賢明','けんめい','현명함; 사리에 밝음','状況を正しく判断し、道理にかなった適切な選択ができるさま。','十分な情報がない段階では、結論を急がないのが賢明だ。','충분한 정보가 없는 단계에서는 결론을 서두르지 않는 것이 현명하다.'),
('n1-1394','2026-10-15','適宜','てきぎ','적절히; 필요에 따라; 수시로','その時の状況・必要性に応じて、ふさわしい方法や時期を選んで行うさま。','進捗状況に応じて、担当者を適宜追加してください。','진행 상황에 따라 담당자를 적절히 추가해 주세요.'),
('n1-1403','2026-10-15','仰ぐ','あおぐ','우러르다; 올려다보다; 지시·도움을 구하다','上を見上げる。また、人を尊敬する、あるいは目上の人に指示・判断・援助を求める。','判断に迷ったため、責任者の指示を仰ぐことにした。','판단이 어려워 책임자의 지시를 구하기로 했다.'),
('n1-1417','2026-10-16','漏らす','もらす','누설하다; 빠뜨리다; 새게 하다','秘密・情報・本音などを外に出す。また、必要な項目を抜かしてしまう、液体などを外へ漏れさせる。','担当者が発表前の情報を外部に漏らしたことが問題になった。','담당자가 발표 전 정보를 외부에 누설한 것이 문제가 됐다.'),
('n1-1439','2026-10-16','巧み','たくみ','능숙함; 교묘함','技術・表現・方法などが非常に上手で、工夫されているさま。','作者は巧みな構成で読者の関心を最後まで引きつける。','작가는 능숙한 구성으로 독자의 관심을 끝까지 끌어당긴다.'),
('n1-1477','2026-10-16','富む','とむ','풍부하다; 많이 지니다','財産・資源・才能・変化などを豊かに持っている。','この地域は自然に富み、四季を通じて多くの観光客が訪れる。','이 지역은 자연이 풍부해 사계절 내내 많은 관광객이 찾는다.'),
('n1-1478','2026-10-16','打ち込む','うちこむ','박아 넣다; 몰두하다; 전념하다','物を強く打って中へ入れる。また、仕事・研究・趣味など一つのことに集中して取り組む。','彼は仕事の後も毎日二時間、資格試験の勉強に打ち込んでいる。','그는 퇴근 후에도 매일 두 시간 자격시험 공부에 몰두하고 있다.'),
('n1-1507','2026-10-16','久しい','ひさしい','오래되다; 오랜 시간이 지나다','ある時から長い時間が経っている。','彼とは久しく会っていなかったが、再会するとすぐ昔の話で盛り上がった。','그와는 오랫동안 만나지 못했지만 재회하자 곧 옛이야기로 분위기가 달아올랐다.'),
('n1-1508','2026-10-16','無念','むねん','분함; 원통함; 유감스러움','望みを果たせず、非常に悔しく残念に思うこと。','決勝直前のけがで出場を断念することになり、本人は無念をにじませた。','결승 직전 부상으로 출전을 포기하게 되어 본인은 분함을 드러냈다.'),
('n1-1585','2026-10-16','高尚','こうしょう','고상함; 수준이 높음','思想・趣味・内容などが上品で、精神的・知的な水準が高いさま。','高尚な理想を語るだけでなく、実行可能な方法も示す必要がある。','고상한 이상을 말하는 것뿐 아니라 실행 가능한 방법도 제시할 필요가 있다.'),
('n1-1596','2026-10-16','志す','こころざす','뜻하다; 목표로 삼다','将来ある職業・目標を実現しようと心に決める。','高校時代の経験をきっかけに、医師を志すようになった。','고등학교 시절의 경험을 계기로 의사를 목표로 하게 되었다.'),
('n1-1655','2026-10-16','遠ざかる','とおざかる','멀어지다; 희박해지다','距離・関係・可能性などが次第に遠くなる。','追加の遅延が発生し、予定どおりの完成はさらに遠ざかった。','추가 지연이 발생해 예정대로 완성할 가능성이 더 멀어졌다.'),
('n1-1657','2026-10-16','窮屈','きゅうくつ','비좁음; 답답함; 제약이 많음','空間が狭くて自由に動きにくい。また、規則・雰囲気などに拘束されて自由がない。','細かい規則が多すぎると、現場は窮屈に感じる。','세세한 규칙이 너무 많으면 현장은 답답하게 느낀다.'),
('n1-1659','2026-10-16','裁く','さばく','재판하다; 판단하다','法律・基準などに基づいて罪・是非・優劣を判断する。','裁判官は提出された証拠に基づいて事件を裁く。','재판관은 제출된 증거를 바탕으로 사건을 재판한다.'),
('n1-1675','2026-10-16','巧妙','こうみょう','교묘함; 정교하고 능숙함','方法・仕組みなどが非常にうまく考えられていて、容易には気づきにくいさま。','巧妙に作られた偽サイトは本物と見分けにくい。','교묘하게 만들어진 가짜 사이트는 진짜와 구별하기 어렵다.'),
('n1-1703','2026-10-16','怠慢','たいまん','태만; 게으름','すべき仕事・義務を真面目に行わず、怠けること。','点検を怠ったのは管理上の怠慢だと指摘された。','점검을 소홀히 한 것은 관리상의 태만이라고 지적됐다.'),
('n1-1704','2026-10-16','あべこべ','あべこべ','거꾸로; 반대로 뒤바뀜','順序・位置・関係などが本来とは逆になっているさま。','送信先と送信元をあべこべに入力してしまった。','수신처와 발신처를 거꾸로 입력해 버렸다.'),
('n1-1714','2026-10-16','ややこしい','ややこしい','복잡하고 까다롭다; 헷갈리다','事情・仕組み・関係などが複雑で、理解・処理しにくい。','例外条件が多く、この手続きはかなりややこしい。','예외 조건이 많아 이 절차는 꽤 복잡하고 까다롭다.'),
('n1-1751','2026-10-16','経る','へる','거치다; 경과하다; 경험하다','ある場所・段階・過程を通る。また、時間が過ぎる。','複数の審査を経て、ようやく新しい制度の導入が正式に決まった。','여러 심사를 거쳐 마침내 새 제도의 도입이 정식으로 결정됐다.'),
('n1-1756','2026-10-16','図る','はかる','도모하다; 꾀하다; 추진하다','目的を実現するため、方法を考えて実行しようとする。','業務手順を見直し、作業時間の大幅な短縮を図る。','업무 절차를 재검토해 작업 시간의 대폭적인 단축을 도모한다.'),
('n1-1826','2026-10-16','担う','になう','맡다; 짊어지다; 담당하다','責任・役割・任務などを引き受けて受け持つ。','次世代を担う技術者を育成することが、会社の重要な課題になっている。','다음 세대를 이끌 기술자를 육성하는 것이 회사의 중요한 과제가 되고 있다.'),
('n1-1840','2026-10-16','高まる','たかまる','높아지다; 고조되다; 향상되다','程度・水準・関心・気運などが以前より高くなる。','個人情報の扱いに対する社会的な関心は年々高まっている。','개인정보 취급에 대한 사회적 관심은 해마다 높아지고 있다.'),
('n1-1854','2026-10-16','いい加減','いいかげん','적당한; 무책임한; 대충인; 어지간히','程度がほどよいこと。一方で、やり方が不十分・無責任・適当であるという否定的な意味にも用いる。','いい加減な確認で公開すると、後から重大な問題につながりかねない。','대충 확인한 뒤 공개하면 나중에 중대한 문제로 이어질 수 있다.');
INSERT INTO _n1_b2_words_0100(source_key,study_date,word,reading,meaning_ko,meaning_ja,example_ja,example_ko) VALUES
('n1-1858','2026-10-17','生かす','いかす','살리다; 활용하다; 발휘하게 하다','命を保たせる。また、能力・経験・特徴などを有効に利用して役立てる。','前のプロジェクトで得た経験を、新しいシステムの設計に生かしたい。','이전 프로젝트에서 얻은 경험을 새 시스템 설계에 활용하고 싶다.'),
('n1-1885','2026-10-17','試みる','こころみる','시도하다; 시험해 보다; 해 보다','結果がどうなるか確かめるため、ある方法・行為を実際にやってみる。','従来の方法で解決できなかったため、新しい手順を試みることにした。','기존 방법으로 해결할 수 없어 새로운 절차를 시도해 보기로 했다.'),
('n1-1933','2026-10-17','値する','あたいする','~할 가치가 있다; ~할 만하다; 값하다','ある評価・行為を受けるだけの価値や資格がある。','彼の長年にわたる努力は、十分に高く評価するに値する。','그의 오랜 노력은 충분히 높이 평가할 가치가 있다.'),
('n1-1942','2026-10-17','成り立つ','なりたつ','성립하다; 이루어지다; 구성되다; 유지되다','物事・関係・条件などが成立する。また、複数の要素から構成される、あるいは生活・事業などが維持できる。','このサービスは多くの利用者からの月額料金で成り立っている。','이 서비스는 많은 이용자의 월 이용료로 유지되고 있다.'),
('n1-1950','2026-10-17','授ける','さずける','주다; 수여하다; 전수하다','目上の者などが、地位・資格・物・知識・技術などを与える。','師匠は長年の修行を終えた弟子に、秘伝の技を授けた。','스승은 오랜 수행을 마친 제자에게 비전의 기술을 전수했다.'),
('n1-1980','2026-10-17','司る','つかさどる','관장하다; 담당하다; 지배하다','ある仕事・機能などを責任を持って管理する。','この部署は社内システムの運用を司っている。','이 부서는 사내 시스템 운영을 관장하고 있다.'),
('n1-2014','2026-10-17','当てはまる','あてはまる','해당하다; 들어맞다; 적용되다','条件・規則・例などにぴったり合う。','この条件に当てはまる人だけが申請できる。','이 조건에 해당하는 사람만 신청할 수 있다.'),
('n1-2027','2026-10-17','禁ずる','きんずる','금하다; 금지하다; 억누르다','ある行為をしてはいけないとする。また、感情などを抑える。','この区域では立ち入りを禁ずる。','이 구역은 출입을 금한다.'),
('n1-2095','2026-10-17','一律','いちりつ','일률적임; 획일적임; 동일하게','すべてを同じ基準・方法で扱うこと。','料金を一律千円に設定した。','요금을 일률적으로 1,000엔으로 정했다.'),
('n1-2111','2026-10-17','傾ける','かたむける','기울이다; 집중하다; 쏟다','物を斜めにする。また、注意・力・心などを一つの対象に集中する。','相手の話に静かに耳を傾けた。','상대의 이야기에 조용히 귀를 기울였다.'),
('n1-2125','2026-10-17','乱れる','みだれる','흐트러지다; 어지러워지다; 혼란해지다','整っていたもの・秩序・心などが崩れて不規則になる。','強い風で髪が乱れた。','강한 바람에 머리가 흐트러졌다.'),
('n1-2126','2026-10-17','障る','さわる','지장을 주다; 해가 되다; 방해하다','何かの妨げになる。また、健康などに悪い影響を与える。','夜更かしは体に障る。','밤샘은 몸에 해롭다.'),
('n1-2201','2026-10-17','取り締まる','とりしまる','단속하다; 감독하다; 통제하다','法律・規則に反する行為がないよう監督・規制する。','警察が違法駐車を厳しく取り締まっている。','경찰이 불법 주차를 엄격히 단속하고 있다.'),
('n1-2204','2026-10-17','円満','えんまん','원만함; 화목함','人間関係・物事の進行などが穏やかで、争いなくうまくいっていること。','話し合いによって問題は円満に解決した。','대화를 통해 문제는 원만하게 해결되었다.'),
('n1-2230','2026-10-17','諮る','はかる','상의하다; 자문을 구하다','ある問題について人や機関に意見を求める。','重要な案件なので専門家に諮ることにした。','중요한 안건이라 전문가에게 자문을 구하기로 했다.'),
('n1-2256','2026-10-17','侵す','おかす','침범하다; 침해하다; 침략하다','他人の領域・権利・尊厳などに不当に入り込み、害する。','他人のプライバシーを侵してはいけない。','타인의 사생활을 침해해서는 안 된다.'),
('n1-2274','2026-10-17','不景気','ふけいき','불경기; 경기 침체','経済活動が停滞し、生産・消費・雇用などが低調な状態。','不景気の影響で売り上げが大きく落ち込んだ。','불경기의 영향으로 매출이 크게 감소했다.'),
('n1-2297','2026-10-17','繕う','つくろう','수선하다; 꿰매다; 고치다; 겉을 꾸미다','破れた所などを直す。また、外見・体裁などを整える。','祖母は破れた靴下を丁寧に繕ってくれた。','할머니는 찢어진 양말을 정성껏 꿰매 주셨다.'),
('n1-2359','2026-10-17','冷淡','れいたん','냉담함; 무관심하고 차가움','人や物事に関心・思いやりを示さず、態度が冷たいこと。','彼の冷淡な態度に、周囲の人は戸惑った。','그의 냉담한 태도에 주변 사람들이 당황했다.'),
('n1-2376','2026-10-17','瞑る','つぶる','눈을 감다','まぶたを閉じて目を覆う。','少し目を瞑って休んだ。','잠깐 눈을 감고 쉬었다.'),
('n1-2387','2026-10-18','揺さぶる','ゆさぶる','세게 흔들다; 뒤흔들다; 충격을 주다','強く揺り動かす。また、心・社会・制度などに大きな衝撃を与える。','その事件は社会全体を大きく揺さぶった。','그 사건은 사회 전체를 크게 뒤흔들었다.'),
('n1-2398','2026-10-18','貶す','けなす','헐뜯다; 깎아내리다; 폄하하다','人・物の欠点を取り上げて悪く言い、価値を低く評価する。','他人の努力を簡単に貶すべきではない。','다른 사람의 노력을 쉽게 깎아내려서는 안 된다.'),
('n1-2465','2026-10-18','自ずから','おのずから','저절로; 자연히; 자연스럽게','特別に働きかけなくても自然にそうなるさま。','経験を積めば、自ずから判断力も身についてくる。','경험을 쌓으면 자연히 판단력도 생긴다.'),
('n1-2496','2026-10-18','結び付く','むすびつく','결부되다; 연결되다; 관련되다','物事どうしが関係を持つ。つながる。','日々の努力が最終的な成果に結び付く。','매일의 노력이 최종적인 성과로 이어진다.'),
('n1-2513','2026-10-18','手掛ける','てがける','다루다; 맡아서 하다; 직접 관여하다; 제작하다','仕事・制作などを自ら担当し、取り組む。また、世話や管理をする。','彼はこれまで多くの企業サイトの設計を手掛けてきた。','그는 지금까지 많은 기업 사이트 설계를 맡아 왔다.'),
('n1-2584','2026-10-18','賄う','まかなう','충당하다; 마련하다; 식사를 제공하다','必要な費用・物資などを用意して不足を補う。また、食事を提供する。','イベント費用は参加費で賄う予定だ。','행사 비용은 참가비로 충당할 예정이다.'),
('n1-2626','2026-10-18','遮る','さえぎる','가로막다; 막다; 차단하다','進行・視線・光・音などを途中で妨げ、通らないようにする。','厚い雲が日差しを遮った。','두꺼운 구름이 햇빛을 가렸다.'),
('n1-2632','2026-10-18','空しい','むなしい','허무하다; 헛되다; 공허하다','成果・価値・手応えがなく、心が満たされない。','努力が全く評価されず、空しい気持ちになった。','노력이 전혀 평가받지 못해 허무한 기분이 들었다.'),
('n1-2637','2026-10-18','絶つ','たつ','끊다; 단절하다; 끊어 버리다','続いている関係・習慣・交通などを完全に切る。','悪い習慣を絶つために生活を見直した。','나쁜 습관을 끊기 위해 생활을 다시 점검했다.'),
('n1-2640','2026-10-18','即する','そくする','부합하다; 따르다; ~에 입각하다','事実・基準・状況などに合うようにする。基づく。','現場の実情に即した制度が必要だ。','현장의 실정에 맞는 제도가 필요하다.'),
('n1-2718','2026-10-18','見っともない','みっともない','보기 흉하다; 창피하다; 꼴사납다','外見・態度などが体裁悪く、恥ずかしい。','人前でそんな言い争いをするのは見っともない。','사람들 앞에서 그런 말다툼을 하는 것은 꼴사납다.'),
('n1-2747','2026-10-18','捗る','はかどる','진척되다; 순조롭게 진행되다','仕事・作業などが順調に進む。','静かな場所に移ったら作業が捗った。','조용한 장소로 옮겼더니 작업이 순조롭게 진행됐다.'),
('n1-2780','2026-10-18','区々','まちまち','제각각; 가지각색; 일정하지 않음','それぞれ異なっていて、統一されていないさま。','参加者の意見はまちまちだった。','참가자들의 의견은 제각각이었다.'),
('n1-2842','2026-10-18','労る','いたわる','위로하다; 돌보다; 배려하다','弱い立場や疲れている相手を思いやり、大切にする。','忙しい時ほど互いの体を労ることが大切だ。','바쁠 때일수록 서로의 몸을 배려하는 것이 중요하다.'),
('n1-2844','2026-10-18','一挙に','いっきょに','단숨에; 한꺼번에; 일거에','一度の動作・機会でまとめて行うさま。','新機能を一挙に公開した。','새 기능을 한꺼번에 공개했다.'),
('n1-2905','2026-10-18','弛む','たるむ','느슨해지다; 처지다; 해이해지다','張っていたものがゆるむ。また、気持ち・規律が緩む。','長く使っているうちにロープが弛んできた。','오랫동안 쓰는 동안 로프가 느슨해졌다.'),
('n1-2956','2026-10-18','齎らす','もたらす','가져오다; 초래하다','物や結果・影響などを持ってくる。生じさせる。','新しい技術は社会に大きな変化をもたらした。','새로운 기술은 사회에 큰 변화를 가져왔다.'),
('n1-2959','2026-10-18','止むを得ない','やむをえない','어쩔 수 없다; 부득이하다','他に方法がなく、そうするしかない。','悪天候のため、試合の中止はやむを得ない。','악천후 때문에 경기 중지는 어쩔 수 없다.'),
('n1-0709','2026-10-18','不意','ふい','불의; 갑작스러움; 뜻밖','予想・準備していない突然のこと。','不意の質問にも落ち着いて答えられるよう、想定外のケースまで練習しておいた。','뜻밖의 질문에도 침착하게 답할 수 있도록 예상 밖의 경우까지 연습해 두었다.'),
('n1-0710','2026-10-18','気質','かたぎ','기질; 특정 집단에 전형적인 성향','職業・身分・時代などに特有の考え方や性格の傾向。','細部まで妥協しない職人気質が、製品の高い品質を支えている。','세부까지 타협하지 않는 장인 기질이 제품의 높은 품질을 뒷받침하고 있다.');
INSERT INTO _n1_b2_words_0100(source_key,study_date,word,reading,meaning_ko,meaning_ja,example_ja,example_ko) VALUES
('n1-0718','2026-10-19','改定','かいてい','개정; 규정·가격 등을 새로 정함','すでに定められている制度・規則・価格などを変更して新しく定めること。','原材料費の上昇を受け、来月からサービス料金を改定する。','원재료비 상승을 반영해 다음 달부터 서비스 요금을 개정한다.'),
('n1-0725','2026-10-19','除外','じょがい','제외; 배제','対象・範囲・計算などから取り除いて含めないこと。','条件を満たさない申請は審査の対象から除外される。','조건을 충족하지 못한 신청은 심사 대상에서 제외된다.'),
('n1-0727','2026-10-19','交易','こうえき','교역; 무역','国・地域どうしが物資や商品を交換・売買すること。','この港町は古くから海外との交易によって発展してきた。','이 항구 도시는 예부터 해외와의 교역으로 발전해 왔다.'),
('n1-0735','2026-10-19','決算','けっさん','결산; 회계 마감','一定期間の収入・支出・資産・負債などを整理し、経営成績や財政状態を確定すること。','年度末の決算に向けて、各部門が経費の確認を進めている。','연도 말 결산을 위해 각 부서가 경비 확인을 진행하고 있다.'),
('n1-0746','2026-10-19','運搬','うんぱん','운반; 운송','物品・資材などを別の場所へ運ぶこと。','大型機械の運搬には専用の車両と事前の道路確認が必要だ。','대형 기계 운반에는 전용 차량과 사전 도로 확인이 필요하다.'),
('n1-0749','2026-10-19','連帯','れんたい','연대; 공동 책임','複数の人や組織が結びつき、共同して行動したり責任を負ったりすること。','地域の住民が連帯して、災害時の支援体制を整えた。','지역 주민들이 연대해 재해 시 지원 체계를 정비했다.'),
('n1-0757','2026-10-19','運輸','うんゆ','운수; 운송','人や貨物を交通機関によって運ぶこと。また、それに関する事業。','燃料費の高騰は運輸業界の経営に大きな影響を与えている。','연료비 급등은 운수업계 경영에 큰 영향을 주고 있다.'),
('n1-0759','2026-10-19','志向','しこう','지향; 특정 방향을 추구함','意識・関心・行動が、ある方向や目標を目指すこと。','近年は環境志向の消費者が増え、再利用できる製品が注目されている。','최근에는 환경 지향적인 소비자가 늘어 재사용 가능한 제품이 주목받고 있다.'),
('n1-0762','2026-10-19','語源','ごげん','어원','ある語がどのように生まれ、どの形から成立したかという由来。','言葉の語源を調べると、昔の文化や考え方が見えてくることがある。','말의 어원을 조사하면 옛 문화와 사고방식이 보이는 경우가 있다.'),
('n1-0763','2026-10-19','周期','しゅうき','주기; 반복되는 기간','同じ現象・状態が繰り返されるとき、一回分が終わって次に同じ状態になるまでの期間。','この装置は一定の周期で自動的に点検処理を行う。','이 장치는 일정한 주기로 자동 점검 처리를 한다.'),
('n1-0765','2026-10-19','寄与','きよ','기여; 공헌','ある目的・成果の実現に役立つこと。','この研究成果は医療技術の向上に大きく寄与すると期待されている。','이 연구 성과는 의료 기술 향상에 크게 기여할 것으로 기대되고 있다.'),
('n1-0766','2026-10-19','集計','しゅうけい','집계; 합산','複数の数値・データを集めてまとめ、合計や結果を出すこと。','アンケート結果を集計したところ、回答者の六割が改善を求めていた。','설문 결과를 집계하니 응답자의 60%가 개선을 요구하고 있었다.'),
('n1-0771','2026-10-19','議案','ぎあん','의안; 회의 안건','議会・会議などで審議・決定するために提出される案。','新しい予算案は来週の総会で正式な議案として審議される。','새 예산안은 다음 주 총회에서 정식 의안으로 심의된다.'),
('n1-0773','2026-10-19','議決','ぎけつ','의결; 결의','会議・議会で審議したうえで、正式に意思を決定すること。','条例の改正案は賛成多数で議決された。','조례 개정안은 찬성 다수로 의결되었다.'),
('n1-0776','2026-10-19','反響','はんきょう','반향; 큰 반응; 울림','音が反射して響き返ること。また、出来事・発言などに対して社会から生じる反応。','新製品の発表は予想以上の反響を呼び、問い合わせが急増した。','신제품 발표는 예상 이상의 반향을 일으켜 문의가 급증했다.'),
('n1-0779','2026-10-19','様相','ようそう','양상; 모습; 상태','物事・現象が示している全体的な姿・状態・ありさま。','技術の進歩によって、働き方は十年前とは大きく異なる様相を呈している。','기술 발전으로 일하는 방식은 10년 전과 크게 다른 양상을 보이고 있다.'),
('n1-0781','2026-10-19','変遷','へんせん','변천; 변화 과정','時代の流れとともに、状態・制度・考え方などが移り変わること。','この展示では都市の景観がどのように変遷してきたかを写真で紹介している。','이 전시에서는 도시 경관이 어떻게 변천해 왔는지를 사진으로 소개하고 있다.'),
('n1-0799','2026-10-19','労力','ろうりょく','노력; 수고; 노동력','仕事や作業のために費やす身体的・精神的な力。','自動化によって、単純作業にかかる時間と労力を大幅に減らせた。','자동화로 단순 작업에 드는 시간과 노력을 크게 줄일 수 있었다.'),
('n1-0803','2026-10-19','成熟','せいじゅく','성숙; 충분히 성장함','生物・人の心身・社会・技術などが十分に発達し、安定した段階に達すること。','市場が成熟すると、企業は価格だけでなくサービスの質でも競うようになる。','시장이 성숙하면 기업은 가격뿐 아니라 서비스 품질로도 경쟁하게 된다.'),
('n1-0804','2026-10-19','外貨','がいか','외화; 외국 통화','自国以外の国の通貨。','海外旅行の前に、必要な分だけ外貨へ両替しておいた。','해외여행 전에 필요한 만큼 외화로 환전해 두었다.'),
('n1-0820','2026-10-20','学説','がくせつ','학설; 학문적 이론','学問上の問題について、研究にもとづいて立てられた理論・主張。','新しい発見によって、長く支持されてきた学説が見直される可能性がある。','새로운 발견으로 오랫동안 지지받아 온 학설이 재검토될 가능성이 있다.'),
('n1-0821','2026-10-20','密度','みつど','밀도','一定の体積・面積・空間の中に、物質・人・情報などがどの程度集中しているかを表す度合い。物理では単位体積あたりの質量。','都市部では人口密度が高く、交通や住宅の問題が起こりやすい。','도시 지역은 인구 밀도가 높아 교통과 주택 문제가 생기기 쉽다.'),
('n1-0825','2026-10-20','見地','けんち','견지; 관점; 입장','物事を考えたり判断したりするときの立場・観点。','安全性の見地から、この設備は定期的に交換する必要がある。','안전성의 관점에서 이 설비는 정기적으로 교체할 필요가 있다.'),
('n1-0828','2026-10-20','還元','かんげん','환원; 되돌려 줌','もとの状態・形に戻すこと。また、利益・成果などを関係者や社会へ返すこと。化学では酸化物などから酸素を取り除く反応もいう。','企業は事業で得た利益の一部を地域社会へ還元している。','기업은 사업에서 얻은 이익 일부를 지역사회에 환원하고 있다.'),
('n1-0831','2026-10-20','起点','きてん','기점; 출발점','道路・路線・物事などが始まる地点・基準となる点。','この駅を起点にして、山間部へ向かうバス路線が三本伸びている。','이 역을 기점으로 산간 지역으로 향하는 버스 노선 세 개가 뻗어 있다.'),
('n1-0836','2026-10-20','野党','やとう','야당','議会政治で、現在政権を担当していない政党。','野党は政府案に反対し、修正案を国会に提出した。','야당은 정부안에 반대하며 수정안을 국회에 제출했다.'),
('n1-0837','2026-10-20','同調','どうちょう','동조; 보조를 맞춤','他人の意見・主張・行動などに賛成して、それに合わせること。','周囲の意見に安易に同調せず、自分で根拠を確かめることが大切だ。','주변 의견에 쉽게 동조하지 말고 스스로 근거를 확인하는 것이 중요하다.'),
('n1-0843','2026-10-20','討議','とうぎ','토의; 논의','複数の人が一つの問題について意見を出し合い、詳しく議論すること。','委員会では新制度の課題について二時間にわたり討議した。','위원회에서는 새 제도의 과제에 대해 두 시간에 걸쳐 토의했다.'),
('n1-0847','2026-10-20','体裁','ていさい','체재; 형식; 체면','外から見た形式・見た目・整い方。また、世間に対する体面。','内容は変えず、報告書の体裁だけを社内基準に合わせて整えた。','내용은 바꾸지 않고 보고서 형식만 사내 기준에 맞게 정리했다.'),
('n1-0848','2026-10-20','融通','ゆうずう','융통; 융통성; 자금 마련','状況に応じて柔軟に対応すること。また、金銭・物資を必要な所へ回して用立てること。','小さな変更なら現場の判断で融通を利かせられる仕組みにしたい。','작은 변경이라면 현장 판단으로 융통성 있게 대응할 수 있는 구조로 만들고 싶다.'),
('n1-0849','2026-10-20','前例','ぜんれい','전례; 선례','以前に起きた同種の事例で、後の判断・処理の参考となるもの。','前例がない案件だからこそ、判断の根拠を明確に残す必要がある。','전례가 없는 안건이기 때문에 판단 근거를 명확히 남길 필요가 있다.'),
('n1-0865','2026-10-20','享受','きょうじゅ','향유; 누림','利益・権利・恩恵・楽しみなどを受け、十分に味わうこと。','誰もが教育を受ける権利を平等に享受できる社会が望まれる。','누구나 교육받을 권리를 평등하게 누릴 수 있는 사회가 바람직하다.'),
('n1-0867','2026-10-20','責務','せきむ','책무; 책임과 의무','立場・役割にともなって果たすべき責任・義務。','管理者には利用者の個人情報を適切に守る責務がある。','관리자에게는 이용자의 개인정보를 적절히 보호할 책무가 있다.'),
('n1-0873','2026-10-20','就業','しゅうぎょう','취업; 일을 함','職業について働くこと。また、勤務を開始すること。','就業時間は午前九時から午後六時までと定められている。','근무 시간은 오전 9시부터 오후 6시까지로 정해져 있다.'),
('n1-0876','2026-10-20','清算','せいさん','청산; 정산','金銭上の貸し借り・債権債務などを計算して処理し、関係を終わらせること。','出張後、交通費と宿泊費をまとめて清算した。','출장 후 교통비와 숙박비를 한꺼번에 정산했다.'),
('n1-0878','2026-10-20','誇張','こちょう','과장; 실제보다 부풀림','実際よりも大きく・強く・重大であるように表現すること。','商品の効果を誇張して宣伝すると、消費者の信頼を失う。','상품 효과를 과장해 광고하면 소비자의 신뢰를 잃는다.'),
('n1-0883','2026-10-20','鉄鋼','てっこう','철강','鉄と鋼の総称。また、それらを材料として扱う産業分野。','自動車産業の動向は鉄鋼需要にも大きく影響する。','자동차 산업의 동향은 철강 수요에도 큰 영향을 준다.'),
('n1-0889','2026-10-20','感触','かんしょく','감촉; 촉감; 느낌','物に触れたときの感覚。また、経験・交渉などから得られる手応えや印象。','試作品を触った感触は良く、操作もしやすかった。','시제품을 만져 본 감촉은 좋았고 조작도 쉬웠다.'),
('n1-0890','2026-10-20','非行','ひこう','비행; 일탈 행위','特に青少年が、法律・社会規範・道徳から外れた行動をすること。','非行を防ぐには、罰だけでなく家庭や地域の支援も重要だ。','비행을 막으려면 처벌뿐 아니라 가정과 지역사회의 지원도 중요하다.'),
('n1-0894','2026-10-20','磁気','じき','자기; 자성','磁石・電流などに関係する、物体を引きつけたり反発させたりする性質・作用。','磁気カードは強い磁石の近くに置くと読み取れなくなることがある。','마그네틱 카드는 강한 자석 가까이에 두면 읽히지 않을 수 있다.');
INSERT INTO _n1_b2_words_0100(source_key,study_date,word,reading,meaning_ko,meaning_ja,example_ja,example_ko) VALUES
('n1-0896','2026-10-21','比例','ひれい','비례','一方の量が変化すると、それに応じて他方の量も一定の関係で変化すること。','作業量に比例して、必要な処理時間も増えていく。','작업량에 비례해 필요한 처리 시간도 늘어난다.'),
('n1-0897','2026-10-21','公団','こうだん','공단; 공공사업 법인','公共的な事業を行うため、国などによって設立された法人。日本では旧制度上の組織名として多く用いられた。','その住宅地は旧公団が大規模に開発したことで知られている。','그 주택지는 구 공단이 대규모로 개발한 곳으로 알려져 있다.'),
('n1-0902','2026-10-21','器官','きかん','기관; 생물체의 기관','生物の体を構成し、特定の形・働きを持つ部分。','心臓は全身に血液を送る重要な器官である。','심장은 전신에 혈액을 보내는 중요한 기관이다.'),
('n1-0911','2026-10-21','公用','こうよう','공용; 공무상 사용','国・自治体・組織などの公式な用務のために使うこと。','この車両は公用のため、私的な目的では利用できない。','이 차량은 공무용이어서 사적인 목적으로 이용할 수 없다.'),
('n1-0913','2026-10-21','元素','げんそ','원소','化学的な方法ではそれ以上簡単な物質に分けられない、物質を構成する基本的な種類。','水は水素と酸素という二種類の元素からできている。','물은 수소와 산소라는 두 종류의 원소로 이루어져 있다.'),
('n1-0914','2026-10-21','着工','ちゃっこう','착공; 공사를 시작함','建築・土木などの工事を実際に始めること。','新しい病院は来春に着工し、二年後の完成を目指している。','새 병원은 내년 봄 착공해 2년 후 완공을 목표로 하고 있다.'),
('n1-0919','2026-10-21','換算','かんさん','환산; 다른 단위로 바꾸어 계산함','ある単位・基準で表された数量を、別の単位・基準に直して計算すること。','金額を現在の為替レートで円に換算すると、およそ十万円になる。','금액을 현재 환율로 엔화로 환산하면 약 10만 엔이 된다.'),
('n1-0921','2026-10-21','境遇','きょうぐう','처지; 놓인 환경과 상황','人が置かれている生活上・社会上の立場や環境。','似た境遇で育った二人は、互いの苦労をよく理解していた。','비슷한 처지에서 자란 두 사람은 서로의 고생을 잘 이해하고 있었다.'),
('n1-0924','2026-10-21','長編','ちょうへん','장편; 긴 작품','小説・映画などで、内容が長く大規模な作品。','その監督は十年ぶりに長編映画を発表した。','그 감독은 10년 만에 장편 영화를 발표했다.'),
('n1-0934','2026-10-21','否決','ひけつ','부결','会議・議会などで、提案・議案を認めないと決定すること。','予算案は賛成票が過半数に届かず否決された。','예산안은 찬성표가 과반수에 미치지 못해 부결됐다.'),
('n1-0935','2026-10-21','書評','しょひょう','서평','本の内容・価値などを批評し評価した文章。','新聞に掲載された書評を読んで、その本に興味を持った。','신문에 실린 서평을 읽고 그 책에 관심을 갖게 됐다.'),
('n1-0938','2026-10-21','採算','さいさん','채산; 수지 타산','収入と費用を比較したとき、事業として利益が出るかどうかの計算。','利用者が少なすぎるため、この路線は採算が取れていない。','이용자가 너무 적어 이 노선은 수지가 맞지 않고 있다.'),
('n1-0939','2026-10-21','採決','さいけつ','표결; 의결을 위한 투표','会議で議案について賛否を問い、決定すること。','十分な討議を終えた後、議長は議案の採決に入った。','충분한 토의를 마친 뒤 의장은 의안 표결에 들어갔다.'),
('n1-0949','2026-10-21','利潤','りじゅん','이윤; 순이익','事業活動によって得た収益から費用を差し引いて残る利益。','短期的な利潤だけを追求すると、長期的な信頼を失うおそれがある。','단기적인 이윤만 추구하면 장기적인 신뢰를 잃을 우려가 있다.'),
('n1-0962','2026-10-21','財政','ざいせい','재정','国・自治体・団体などが収入と支出を管理・運営すること。また、その状態。','税収が減少したため、自治体は財政の立て直しを迫られている。','세수가 감소해 지자체는 재정 재건을 요구받고 있다.'),
('n1-0978','2026-10-21','背景','はいけい','배경; 배후 사정','後ろに見える景色。また、出来事・問題の背後にある事情・要因。','数字だけでなく、その変化が起きた社会的背景も分析する必要がある。','수치뿐 아니라 그 변화가 일어난 사회적 배경도 분석할 필요가 있다.'),
('n1-0990','2026-10-21','負担','ふたん','부담; 비용·책임을 짊어짐','費用・責任・労力などを引き受けること。また、心身に重く感じられるもの。','手続きを簡素化し、利用者の負担を減らすことが今回の改善目的だ。','절차를 간소화해 이용자의 부담을 줄이는 것이 이번 개선 목적이다.'),
('n1-0995','2026-10-21','崩壊','ほうかい','붕괴; 무너짐','建造物・組織・制度などが崩れて成り立たなくなること。','信頼関係の崩壊を防ぐには、問題を早い段階で共有することが重要だ。','신뢰 관계의 붕괴를 막으려면 문제를 초기 단계에서 공유하는 것이 중요하다.'),
('n1-0999','2026-10-21','降伏','こうふく','항복','戦いで負けを認め、相手に従うこと。','補給路を断たれた部隊は、最終的に降伏を決断した。','보급로가 끊긴 부대는 결국 항복을 결정했다.'),
('n1-1005','2026-10-21','訴訟','そしょう','소송','権利・義務などをめぐる争いについて、裁判所に法的な判断を求める手続き。','両社は長年の訴訟を終え、最終的に和解することで合意した。','두 회사는 오랜 소송을 끝내고 최종적으로 합의하기로 했다.'),
('n1-1015','2026-10-22','根拠','こんきょ','근거; 논거','判断・主張などを支える理由・証拠。','十分な根拠がないまま結論を出すべきではない。','충분한 근거 없이 결론을 내려서는 안 된다.'),
('n1-1020','2026-10-22','長官','ちょうかん','장관; 기관의 최고 책임자','官庁・行政機関などの最高責任者を表す官職名。','長官は記者会見で、新しい安全対策の方針を説明した。','장관은 기자회견에서 새로운 안전 대책의 방침을 설명했다.'),
('n1-1042','2026-10-22','治安','ちあん','치안','社会の安全・秩序が保たれている状態。また、それを維持すること。','観光客の増加に伴い、地域の治安維持も重要な課題となっている。','관광객 증가에 따라 지역의 치안 유지도 중요한 과제가 되고 있다.'),
('n1-1044','2026-10-22','以て','もって','~로써; ~을 가지고; ~을 기하여','手段・方法を表す文語的な語。また『本日をもって』のように時点・区切りを示す。','本日をもって旧制度の受付を終了します。','오늘을 기하여 구제도의 접수를 종료합니다.'),
('n1-1048','2026-10-22','超','ちょう','초-; 매우; 한계를 넘는','基準・範囲を越えること。また口語では『非常に』の意味を加える接頭語。','この装置は従来品を超える高精度な測定を可能にした。','이 장치는 기존 제품을 뛰어넘는 고정밀 측정을 가능하게 했다.'),
('n1-1050','2026-10-22','取り扱い','とりあつかい','취급; 처리; 취급 방법','物・情報・人などを扱うこと。また、その方法・待遇。','個人情報の取り扱いについては社内規程を厳守してください。','개인정보 취급에 대해서는 사내 규정을 엄수해 주세요.'),
('n1-1051','2026-10-22','流し','ながし','싱크대; 개수대','台所などで水を使って物を洗う設備・場所。ほかに古い職業名などの用法もある。','食器を洗った後、流しの周りの水気も拭き取った。','식기를 씻은 뒤 싱크대 주변의 물기도 닦아 냈다.'),
('n1-1052','2026-10-22','試み','こころみ','시도; 시험적인 시도','新しい方法・可能性などを試してみること。','この制度は地域の課題を住民自身で解決しようとする新しい試みだ。','이 제도는 지역 과제를 주민 스스로 해결하려는 새로운 시도다.'),
('n1-1057','2026-10-22','軌道','きどう','궤도; 정상적인 진행 단계','物体が一定の規則で動く道筋。また比喩的に、事業などが順調に進む状態。','新規事業が軌道に乗るまでには予想以上の時間がかかった。','신규 사업이 궤도에 오르기까지 예상보다 많은 시간이 걸렸다.'),
('n1-1067','2026-10-22','エンジニア','エンジニア','엔지니어; 기술자','専門的な工学・技術知識を用いて設計・開発・運用などを行う技術者。','システム障害の原因を特定するため、複数のエンジニアが調査に参加した。','시스템 장애의 원인을 특정하기 위해 여러 엔지니어가 조사에 참여했다.'),
('n1-1068','2026-10-22','仕組み','しくみ','구조; 작동 원리; 체계','複数の要素が組み合わさって働く構造・原理。また、制度・組織の成り立ち。','利用者が迷わないよう、申請の仕組み自体を簡単にする必要がある。','이용자가 헤매지 않도록 신청 구조 자체를 간단하게 할 필요가 있다.'),
('n1-1070','2026-10-22','官僚','かんりょう','관료','国の行政機関で政策の立案・実施などを担う上級公務員。','政策案は官僚だけでなく、現場の専門家の意見も取り入れて作られた。','정책안은 관료뿐 아니라 현장 전문가의 의견도 반영해 만들어졌다.'),
('n1-1072','2026-10-22','貨幣','かへい','화폐','商品・サービスの交換や価値の尺度として社会で使われる金銭。','電子決済の普及により、貨幣の使われ方も大きく変化している。','전자결제 보급으로 화폐의 사용 방식도 크게 변하고 있다.'),
('n1-1075','2026-10-22','キャリア','キャリア','경력; 직업 경로; 운반체·보균자','職業上の経験・経歴。また文脈により、通信事業者・運搬体・病原体の保有者などを指す。','長期的なキャリアを考え、今の仕事で身に付けるべき技能を整理した。','장기적인 경력을 생각해 현재 업무에서 익혀야 할 기술을 정리했다.'),
('n1-1077','2026-10-22','演習','えんしゅう','연습; 실습; 훈련','学んだ知識・方法を実際の問題・訓練で繰り返し実践すること。','講義の後に演習問題を解くことで、理解度を確認する。','강의 후 연습 문제를 풀어 이해도를 확인한다.'),
('n1-1082','2026-10-22','廃棄','はいき','폐기','不要になった物・資料などを捨て、使用しないよう処分すること。','保存期限を過ぎた機密文書は、規程に従って安全に廃棄する。','보존 기한이 지난 기밀 문서는 규정에 따라 안전하게 폐기한다.'),
('n1-1083','2026-10-22','アプローチ','アプローチ','접근; 접근법; 접근하다','対象に近づくこと。また、問題を解決するための方法・考え方。','同じ問題でも、技術面と運用面では異なるアプローチが必要になる。','같은 문제라도 기술 측면과 운영 측면에서는 다른 접근법이 필요하다.'),
('n1-2924','2026-10-22','審判','しんばん','심판; 판정; 재판','物事の是非・勝敗などを判定すること。また、競技で判定を行う人。裁判・審理の意味でも用いる。','試合では公平な審判が求められる。','경기에서는 공정한 심판이 요구된다.'),
('n1-1088','2026-10-22','動員','どういん','동원','目的のために多くの人・物資・組織などを集めて活動させること。','復旧作業には全国の拠点から技術者が動員された。','복구 작업에는 전국 거점에서 기술자가 동원됐다.'),
('n1-1090','2026-10-22','マスコミ','マスコミ','매스컴; 대중매체; 언론','新聞・テレビ・雑誌など、不特定多数に情報を伝える報道機関・媒体の総称。','事件への関心が高まり、現場には多くのマスコミ関係者が集まった。','사건에 대한 관심이 높아져 현장에 많은 언론 관계자가 모였다.');
INSERT INTO _n1_b2_words_0100(source_key,study_date,word,reading,meaning_ko,meaning_ja,example_ja,example_ko) VALUES
('n1-1103','2026-10-23','訴え','うったえ','호소; 소송상의 주장','苦しい事情・要求・意見などを強く伝えること。また、法的救済を求めて申し立てること。','住民の訴えを受け、市は騒音対策の調査を始めた。','주민들의 호소를 받아 시는 소음 대책 조사를 시작했다.'),
('n1-1106','2026-10-23','繊維','せんい','섬유','細長い糸状の物質。衣料の材料や、生物の組織を構成するものなどをいう。','この衣服には再生した化学繊維が使われている。','이 의류에는 재생한 화학 섬유가 사용되고 있다.'),
('n1-1107','2026-10-23','思考','しこう','사고; 생각함','物事について筋道を立てて考え、判断する精神の働き。','複雑な問題ほど、感情だけでなく論理的な思考が求められる。','복잡한 문제일수록 감정뿐 아니라 논리적인 사고가 요구된다.'),
('n1-1113','2026-10-23','成年','せいねん','성년; 법적으로 성인이 된 상태','法律上、一人前の大人として扱われる年齢に達していること。','成年年齢の変更に伴い、契約に関する教育の重要性が増した。','성년 연령 변경에 따라 계약에 관한 교육의 중요성이 커졌다.'),
('n1-1118','2026-10-23','趣旨','しゅし','취지; 주된 목적과 뜻','ある活動・文章・制度などの中心となる目的や考え。','制度の趣旨を理解せずに手続きだけを変えても効果は薄い。','제도의 취지를 이해하지 않고 절차만 바꿔도 효과는 적다.'),
('n1-1131','2026-10-23','貧困','ひんこん','빈곤','生活に必要な所得・資源が不足し、暮らしが困難な状態。','子どもの貧困を減らすには教育と生活の両面から支援が必要だ。','아동 빈곤을 줄이려면 교육과 생활 양면에서 지원이 필요하다.'),
('n1-1132','2026-10-23','取り締まり','とりしまり','단속; 규제 집행','法律・規則に違反する行為がないか監視し、違反者を検挙・処分すること。','事故を減らすため、危険運転の取り締まりが強化された。','사고를 줄이기 위해 위험 운전에 대한 단속이 강화되었다.'),
('n1-1135','2026-10-23','収益','しゅうえき','수익; 사업에서 얻는 이익','事業・投資などによって得られる収入や利益。','広告収入が増え、事業全体の収益も改善した。','광고 수입이 늘어 사업 전체의 수익도 개선되었다.'),
('n1-1143','2026-10-23','振興','しんこう','진흥; 발전을 촉진함','産業・学術・文化などを盛んにし、発展させること。','自治体は観光振興のため、地域資源を生かした企画を進めている。','지자체는 관광 진흥을 위해 지역 자원을 활용한 기획을 추진하고 있다.'),
('n1-1147','2026-10-23','手本','てほん','본보기; 모범; 견본','見習うべき例。また、字・絵・技術などをまねるための見本。','新人にはまず先輩の対応を手本にしてもらう。','신입에게는 우선 선배의 대응을 본보기로 삼게 한다.'),
('n1-1149','2026-10-23','分散','ぶんさん','분산; 흩어짐','一か所に集中しているものを複数の場所・対象に分けること。また、分かれて散ること。','障害の影響を小さくするため、処理を複数のサーバーに分散させている。','장애 영향을 줄이기 위해 처리를 여러 서버에 분산시키고 있다.'),
('n1-1157','2026-10-23','住','じゅう','주거; 생활하는 곳','住むこと、住居に関すること。特に『衣食住』などで生活の住居面を表す。','生活を考えるうえでは、衣食住の安定が基本になる。','생활을 생각할 때는 의식주의 안정이 기본이 된다.'),
('n1-1160','2026-10-23','祈り','いのり','기도; 바람','神仏などに願いを伝えること。また、物事が望ましい結果になるよう強く願う気持ち。','式典では犠牲者への追悼と平和への祈りがささげられた。','식전에서는 희생자 추모와 평화를 위한 기도가 올려졌다.'),
('n1-1165','2026-10-23','アマチュア','アマチュア','아마추어; 비전문가','スポーツ・芸術などを職業としてではなく趣味として行う人。','この大会にはプロだけでなくアマチュアの選手も参加できる。','이 대회에는 프로뿐 아니라 아마추어 선수도 참가할 수 있다.'),
('n1-1166','2026-10-23','奉仕','ほうし','봉사; 헌신','自分の利益を優先せず、他人・社会・組織などのために力を尽くすこと。','地域への奉仕活動として、社員が公園の清掃に参加した。','지역 봉사 활동으로 직원들이 공원 청소에 참여했다.'),
('n1-1172','2026-10-23','革新','かくしん','혁신','古い制度・技術・考え方などを改め、新しいものへ大きく変えること。','技術革新によって、従来は不可能だった処理が短時間でできるようになった。','기술 혁신으로 기존에는 불가능했던 처리를 짧은 시간에 할 수 있게 되었다.'),
('n1-1173','2026-10-23','白状','はくじょう','자백; 사실대로 털어놓음','隠していた罪・過ち・事実などを自分から認めて話すこと。','問い詰められた彼は、ついに自分が資料を持ち出したと白状した。','추궁을 받은 그는 마침내 자신이 자료를 가져갔다고 자백했다.'),
('n1-1182','2026-10-23','滅亡','めつぼう','멸망','国・文明・集団などが滅びて存在しなくなること。','その王国が滅亡した原因については複数の説がある。','그 왕국이 멸망한 원인에 대해서는 여러 설이 있다.'),
('n1-1191','2026-10-23','民俗','みんぞく','민속','ある地域・民族に昔から伝わる生活習慣・信仰・行事・文化など。','研究者は各地の祭りを調査し、地域の民俗を記録している。','연구자는 각지의 축제를 조사해 지역 민속을 기록하고 있다.'),
('n1-1194','2026-10-23','アンケート','アンケート','설문조사; 앙케트','多くの人に同じ質問を行い、意見・実態などを調べる調査。また、その質問票。','研修終了後、参加者に満足度アンケートを実施した。','연수 종료 후 참가자들에게 만족도 설문조사를 실시했다.'),
('n1-1195','2026-10-24','脂肪','しぼう','지방','生物の体内に蓄えられ、エネルギー源などになる物質。','この食品は脂肪の含有量が比較的少ない。','이 식품은 지방 함유량이 비교적 적다.'),
('n1-1196','2026-10-24','繁栄','はんえい','번영; 번창','国・都市・産業・組織などが栄え、豊かになること。','港の発展が地域経済の繁栄につながった。','항구의 발전이 지역 경제의 번영으로 이어졌다.'),
('n1-1209','2026-10-24','逃亡','とうぼう','도망; 도주','捕まること・責任などを避けるため、追われている場所から逃げること。','容疑者は事件後に国外へ逃亡したとみられている。','용의자는 사건 후 국외로 도주한 것으로 보인다.'),
('n1-1210','2026-10-24','攻め','せめ','공세; 공격','相手に対して積極的に攻撃すること。また、その姿勢・方法。','後半は守りより攻めを重視した戦術に切り替えた。','후반에는 수비보다 공격을 중시하는 전술로 전환했다.'),
('n1-1211','2026-10-24','国産','こくさん','국산; 국내 생산','自国で生産・製造されたこと。また、その製品・産物。','この装置には国産の部品が多く使われている。','이 장치에는 국산 부품이 많이 사용되고 있다.'),
('n1-1217','2026-10-24','過労','かろう','과로','健康を損なうほど働きすぎること。また、それによる強い疲労。','過労を防ぐため、勤務時間と休暇取得状況を定期的に確認している。','과로를 막기 위해 근무 시간과 휴가 사용 현황을 정기적으로 확인하고 있다.'),
('n1-1220','2026-10-24','絶望','ぜつぼう','절망','望みがなくなり、もう良い結果を期待できないと感じること。','一度の失敗だけで絶望せず、原因を分析して次に生かすべきだ。','한 번의 실패만으로 절망하지 말고 원인을 분석해 다음에 활용해야 한다.'),
('n1-1224','2026-10-24','威力','いりょく','위력; 강한 효과','相手・物事を圧倒するほどの強い力・効果。','新しい分析手法は大量データを扱う場面で特に威力を発揮する。','새 분석 기법은 대량 데이터를 다루는 상황에서 특히 위력을 발휘한다.'),
('n1-1235','2026-10-24','守備','しゅび','수비; 방어','相手の攻撃を防いで守ること。特にスポーツで自陣・守る側の働きをいう。','このチームは攻撃力だけでなく守備も安定している。','이 팀은 공격력뿐 아니라 수비도 안정적이다.'),
('n1-1239','2026-10-24','首脳','しゅのう','수뇌; 최고 지도자','国・政府・組織などの中心となる最高幹部・指導者。','両国の首脳は会談で経済協力について意見を交わした。','양국 정상은 회담에서 경제 협력에 대해 의견을 나눴다.'),
('n1-1240','2026-10-24','新興','しんこう','신흥; 새롭게 생겨 세력을 얻음','新しい勢力・企業・産業・国などが現れ、発展してくること。','新興企業が新しいサービスで市場に参入している。','신흥 기업이 새로운 서비스로 시장에 진입하고 있다.'),
('n1-1243','2026-10-24','階層','かいそう','계층; 층위','社会的地位・所得・役割などによって分けられた層。また、構造上の上下関係を持つ段階。','システムを複数の階層に分けることで責務を明確にした。','시스템을 여러 계층으로 나눠 책임을 명확히 했다.'),
('n1-1251','2026-10-24','崇拝','すうはい','숭배; 경배','神・宗教的対象、または人物などを非常に尊いものとして敬い仰ぐこと。','その人物を無条件に崇拝するような見方には注意が必要だ。','그 인물을 무조건 숭배하는 식의 시각에는 주의가 필요하다.'),
('n1-1252','2026-10-24','干渉','かんしょう','간섭','本来その人が判断すべき事柄に外部から口や手を出し、影響を与えること。','経営判断に外部が過度に干渉するのは望ましくない。','경영 판단에 외부가 지나치게 간섭하는 것은 바람직하지 않다.'),
('n1-1253','2026-10-24','征服','せいふく','정복','武力などによって国・地域・相手を支配下に置くこと。また比喩的に困難を克服すること。','かつて多くの地域が軍事力によって征服された。','과거 많은 지역이 군사력에 의해 정복되었다.'),
('n1-1254','2026-10-24','捜索','そうさく','수색; 찾아냄','行方不明者・犯人・証拠・物品などを広い範囲で詳しく探すこと。','警察と消防が山中で行方不明者の捜索を続けている。','경찰과 소방이 산속에서 실종자 수색을 계속하고 있다.'),
('n1-1259','2026-10-24','アラブ','アラブ','아랍; 아랍권','主にアラビア語を用い、共通する歴史・文化を持つ中東・北アフリカの人々や地域を指す語。','アラブ諸国は政治・経済・文化の面でそれぞれ異なる特徴を持つ。','아랍 국가들은 정치·경제·문화 면에서 각기 다른 특징을 지닌다.'),
('n1-1264','2026-10-24','模型','もけい','모형; 모델','実物の形・構造を一定の比率で小さく、または分かりやすく再現したもの。','建築模型を使って完成後の空間を説明した。','건축 모형을 이용해 완공 후 공간을 설명했다.'),
('n1-1269','2026-10-24','良心','りょうしん','양심','自分の行為が道徳的に正しいかどうかを内面的に判断する心。','彼は良心に従い、不正を見過ごさずに報告した。','그는 양심에 따라 부정을 묵인하지 않고 보고했다.'),
('n1-1275','2026-10-24','圧迫','あっぱく','압박; 압박함','強い力で押しつけること。また、心理・財政・自由などを強く制限すること。','原材料費の上昇が企業の利益を圧迫している。','원자재 비용 상승이 기업 이익을 압박하고 있다.');
INSERT INTO _n1_b2_words_0100(source_key,study_date,word,reading,meaning_ko,meaning_ja,example_ja,example_ko) VALUES
('n1-1280','2026-10-25','細胞','さいぼう','세포','生物の体を構成する、生命活動の基本となる最小単位。','研究チームは細胞の変化を長期間観察した。','연구팀은 세포의 변화를 장기간 관찰했다.'),
('n1-1285','2026-10-25','救援','きゅうえん','구원; 구조; 구호 지원','災害・事故・戦争などで困難な状況にある人々を助け、必要な物資・人員などを送ること。','被災地には各地から救援物資が届けられた。','재해 지역에는 각지에서 구호 물자가 전달되었다.'),
('n1-1291','2026-10-25','自首','じしゅ','자수','犯罪を犯した者が、捜査機関に自ら出向いて罪を申し出ること。','容疑者は事件の翌日に警察へ自首した。','용의자는 사건 다음 날 경찰에 자수했다.'),
('n1-1292','2026-10-25','申告','しんこく','신고; 신고함','行政機関などに事実・所得・数量などを正式に知らせること。','所得税は期限内に正しく申告する必要がある。','소득세는 기한 내에 정확히 신고할 필요가 있다.'),
('n1-1294','2026-10-25','没収','ぼっしゅう','몰수; 압수','法律・規則などに基づき、財産・物品などを強制的に取り上げること。','不正に得た資産は裁判所の命令で没収された。','부정하게 얻은 자산은 법원 명령으로 몰수되었다.'),
('n1-1297','2026-10-25','花粉','かふん','꽃가루','花の雄しべで作られ、受粉に関わる細かな粉状のもの。','春は花粉が多く飛ぶため、マスクを着ける人が増える。','봄에는 꽃가루가 많이 날려 마스크를 쓰는 사람이 늘어난다.'),
('n1-1298','2026-10-25','質疑','しつぎ','질의; 질문과 답변','疑問点について質問すること。特に会議・講演などで行う質問と応答。','説明の後に十分な質疑の時間を設けた。','설명 후 충분한 질의 시간을 마련했다.'),
('n1-1302','2026-10-25','了承','りょうしょう','양해; 승낙; 이해하고 받아들임','事情・内容を理解したうえで受け入れ、認めること。','日程変更について参加者全員の了承を得た。','일정 변경에 대해 참가자 전원의 양해를 얻었다.'),
('n1-1303','2026-10-25','証','あかし','증거; 증표; 증명','ある事実・気持ち・関係などが本当であることを示す証拠・しるし。','長年続いた協力関係の証として記念品が贈られた。','오랫동안 이어진 협력 관계의 증표로 기념품이 전달되었다.'),
('n1-1305','2026-10-25','土木','どぼく','토목; 토목 공사','道路・橋・河川・堤防など、土地や公共基盤を整備する工事・技術分野。','大雨に備えて河川周辺の土木工事が進められている。','폭우에 대비해 하천 주변 토목 공사가 진행되고 있다.'),
('n1-1308','2026-10-25','疲労','ひろう','피로','仕事・運動・精神的負担などによって心身の力が低下し、疲れること。','長時間勤務による疲労が判断力の低下につながることがある。','장시간 근무로 인한 피로가 판단력 저하로 이어질 수 있다.'),
('n1-1309','2026-10-25','配列','はいれつ','배열; 일정한 순서로 배치함','要素を一定の順序・規則に従って並べること。また、その並び。','画面サイズに応じてボタンの配列を変更する。','화면 크기에 따라 버튼 배열을 변경한다.'),
('n1-1316','2026-10-25','原点','げんてん','원점; 출발점','物事が始まった最初の地点・基本となる考え。数学では座標の基準点。','問題が複雑になったときこそ、企画の原点に戻って考えたい。','문제가 복잡해졌을 때일수록 기획의 원점으로 돌아가 생각하고 싶다.'),
('n1-1324','2026-10-25','鳥居','とりい','도리이; 신사 입구의 문','神社の入口などに立てられる、二本の柱と横木からなる門状の構造物。','参道の入口に大きな朱色の鳥居が立っている。','참배길 입구에 큰 주홍색 도리이가 서 있다.'),
('n1-1327','2026-10-25','私有','しゆう','사유; 개인 소유','土地・財産などを個人や民間団体が所有すること。','この道路の先は私有地のため、許可なく立ち入れない。','이 도로 끝은 사유지이므로 허가 없이 들어갈 수 없다.'),
('n1-1329','2026-10-25','辞退','じたい','사양; 사퇴; 참가를 거절함','勧められた地位・権利・参加・受賞などを自分から断ること。','本人は健康上の理由から大会への出場を辞退した。','본인은 건강상의 이유로 대회 출전을 사양했다.'),
('n1-1330','2026-10-25','拘束','こうそく','구속; 속박; 자유를 제한함','身体・行動・時間などの自由を制限し、自由に動けないようにすること。','長時間の会議で社員を必要以上に拘束しないようにした。','장시간 회의로 직원을 필요 이상으로 붙잡아 두지 않도록 했다.'),
('n1-1332','2026-10-25','国交','こっこう','국교; 국가 간 외교 관계','国家と国家との間に結ばれる公式な外交関係。','両国は長い交渉の末、正式に国交を樹立した。','양국은 긴 협상 끝에 정식으로 국교를 수립했다.'),
('n1-1339','2026-10-25','麻痺','まひ','마비; 기능 정지','神経・筋肉などが正常に働かず、感覚や運動機能が失われること。また比喩的に機能が停止すること。','大雪の影響で都市の交通網が一時的に麻痺した。','폭설의 영향으로 도시 교통망이 일시적으로 마비되었다.'),
('n1-1355','2026-10-25','間柄','あいだがら','사이; 관계','人と人との関係。特に親しさ・立場などから見た関係性。','二人は仕事上だけでなく、家族ぐるみで付き合う間柄だ。','두 사람은 업무뿐 아니라 가족끼리도 교류하는 사이다.'),
('n1-1362','2026-10-26','志望','しぼう','지망; 희망함','進学先・職業・役割などとして、あるものを希望すること。','彼女は大学卒業後、研究職を志望している。','그녀는 대학 졸업 후 연구직을 지망하고 있다.'),
('n1-1367','2026-10-26','懸賞','けんしょう','현상; 상금·상품을 건 공모','作品・回答・情報などを広く募集し、優れたものや条件を満たしたものに賞金・賞品を与えること。','雑誌の懸賞に応募したところ、旅行券が当たった。','잡지 현상 이벤트에 응모했더니 여행권에 당첨됐다.'),
('n1-1368','2026-10-26','歩み','あゆみ','걸음; 행보; 과정','歩くこと。また比喩的に、これまで進んできた過程・歴史。','創業から現在までの会社の歩みを年表にまとめた。','창업부터 현재까지 회사의 발자취를 연표로 정리했다.'),
('n1-1374','2026-10-26','免除','めんじょ','면제','本来負うべき義務・責任・料金などを、特別に負わなくてよいことにすること。','一定の条件を満たす学生は受験料が免除される。','일정 조건을 충족한 학생은 응시료가 면제된다.'),
('n1-1381','2026-10-26','倹約','けんやく','검약; 절약','お金・物・資源などを無駄に使わず、出費を抑えること。','旅行資金を貯めるため、しばらく外食を控えて倹約している。','여행 자금을 모으기 위해 한동안 외식을 줄이며 절약하고 있다.'),
('n1-1382','2026-10-26','閲覧','えつらん','열람','書類・資料・ウェブページなどを開いて内容を見ること。','社外秘の資料は権限を持つ社員だけが閲覧できる。','사외비 자료는 권한이 있는 직원만 열람할 수 있다.'),
('n1-1388','2026-10-26','追跡','ついせき','추적','人・物・情報などの動きや所在を、後を追って調べ続けること。','配送番号を入力すると荷物の現在地を追跡できる。','배송 번호를 입력하면 화물의 현재 위치를 추적할 수 있다.'),
('n1-1390','2026-10-26','願書','がんしょ','원서; 지원서','学校・試験・資格などへの志願内容を記入し、提出する正式な書類。','入学願書は締切日までに郵送しなければならない。','입학 원서는 마감일까지 우편으로 보내야 한다.'),
('n1-1391','2026-10-26','貯蓄','ちょちく','저축; 축적','将来に備えて金銭・財産などを蓄えておくこと。','毎月一定額を貯蓄するため、自動積立を設定した。','매달 일정 금액을 저축하기 위해 자동 적립을 설정했다.'),
('n1-1393','2026-10-26','等級','とうきゅう','등급; 급수','品質・能力・地位などを一定の基準によって段階的に分けた区分。','製品は品質検査の結果に応じて複数の等級に分類される。','제품은 품질 검사 결과에 따라 여러 등급으로 분류된다.'),
('n1-1401','2026-10-26','冠','かん','관; 왕관; 우승·칭호를 나타내는 관','地位・栄誉を象徴する冠。また、『三冠』など、優勝・称号を数える語の一部として用いる。','選手は三つの主要大会を制し、三冠を達成した。','선수는 세 개의 주요 대회에서 우승해 3관왕을 달성했다.'),
('n1-1402','2026-10-26','未開','みかい','미개척; 아직 개발·개척되지 않음','土地・分野などがまだ十分に開発・開拓されていないこと。歴史的には文明発達の程度を表す語としても使われた。','研究チームはまだ未開の分野に挑戦し、新しい方法を探っている。','연구팀은 아직 개척되지 않은 분야에 도전해 새로운 방법을 찾고 있다.'),
('n1-1404','2026-10-26','勧告','かんこく','권고; 공식적으로 조치를 권함','公的機関・組織などが、相手に一定の行動を取るよう正式にすすめること。','監督機関は会社に対し、管理体制を改善するよう勧告した。','감독 기관은 회사에 관리 체제를 개선하도록 권고했다.'),
('n1-1406','2026-10-26','細菌','さいきん','세균; 박테리아','非常に小さな単細胞の微生物の一群。病気・発酵・分解などに関わるものがある。','食中毒を防ぐには、細菌が増えやすい温度で食品を長時間放置しないことが重要だ。','식중독을 막으려면 세균이 증식하기 쉬운 온도에서 식품을 오래 방치하지 않는 것이 중요하다.'),
('n1-1410','2026-10-26','抽選','ちゅうせん','추첨; 제비뽑기','応募者・候補などの中から、くじや乱数などによって公平に選ぶこと。','応募者が定員を超えたため、参加者は抽選で決められる。','지원자가 정원을 초과해 참가자는 추첨으로 결정된다.'),
('n1-1413','2026-10-26','有様','ありさま','모양; 상태; 꼴','物事・人の現在の状態や様子。特に、好ましくない状態を批判的に述べる場合によく使う。','管理が行き届かず、倉庫の中は足の踏み場もない有様だった。','관리가 제대로 되지 않아 창고 안은 발 디딜 틈도 없는 꼴이었다.'),
('n1-1414','2026-10-26','和風','わふう','일본풍; 일본식','建築・料理・服装・デザインなどが日本の伝統的な様式を取り入れていること。','旅館の客室は木と畳を生かした和風のデザインになっている。','료칸 객실은 나무와 다다미를 살린 일본풍 디자인으로 되어 있다.'),
('n1-1418','2026-10-26','賭け','かけ','내기; 도박; 승산이 불확실한 시도','勝敗・結果に金品などをかけること。また、成功するか分からないことに大胆に挑むこと。','十分な検証なしに全機能を一度に公開するのは大きな賭けだ。','충분한 검증 없이 모든 기능을 한꺼번에 공개하는 것은 큰 도박이다.'),
('n1-1433','2026-10-26','形勢','けいせい','형세; 판세; 세력 관계','争い・競争・交渉などで、その時点における双方の力関係や状況。','後半に入ってから試合の形勢が一気に逆転した。','후반에 들어서 경기의 판세가 단숨에 뒤집혔다.'),
('n1-1437','2026-10-26','水源','すいげん','수원; 물의 근원','川・湖・地下水など、水が供給される源となる場所。','森林を守ることは地域の水源を保全することにもつながる。','산림을 보호하는 것은 지역의 수원을 보전하는 것으로도 이어진다.');
INSERT INTO _n1_b2_words_0100(source_key,study_date,word,reading,meaning_ko,meaning_ja,example_ja,example_ko) VALUES
('n1-1442','2026-10-27','採択','さいたく','채택; 선택하여 받아들임','複数の案・提案・決議などから一つを選び、正式に取り上げること。','委員会では修正案が多数決で採択された。','위원회에서는 수정안이 다수결로 채택됐다.'),
('n1-1443','2026-10-27','匹敵','ひってき','필적; 맞먹음','能力・価値・規模などが相手とほぼ同じ程度で、肩を並べること。','新製品の性能は海外の高級機種に匹敵する水準に達した。','신제품 성능은 해외 고급 기종에 필적하는 수준에 도달했다.'),
('n1-1446','2026-10-27','腐敗','ふはい','부패; 썩음; 조직의 타락','有機物が微生物などの作用で腐ること。また比喩的に、組織・政治などが不正によって堕落すること。','食品の腐敗を防ぐため、低温で保存する必要がある。','식품 부패를 막기 위해 저온으로 보관할 필요가 있다.'),
('n1-1447','2026-10-27','整列','せいれつ','정렬; 줄을 맞춤','一定の順序・間隔で、きちんと列を作って並ぶこと。また、並べること。','参加者は係員の指示に従って二列に整列した。','참가자들은 담당자의 지시에 따라 두 줄로 정렬했다.'),
('n1-1448','2026-10-27','岩石','がんせき','암석','地殻などを構成する、鉱物の集合からなる固い物質。','地質調査では岩石の種類や年代を詳しく調べる。','지질 조사에서는 암석의 종류와 연대를 자세히 조사한다.'),
('n1-1453','2026-10-27','保養','ほよう','보양; 요양; 휴양','疲労・病気などから回復するため、体を休めて健康を養うこと。','医師の勧めで数日間温泉地に滞在し、保養することにした。','의사의 권유로 며칠간 온천 지역에 머물며 요양하기로 했다.'),
('n1-1455','2026-10-27','腕前','うでまえ','솜씨; 실력; 기량','技能・技術をどの程度上手に使えるかという実力。','料理人は鮮やかな包丁さばきで見事な腕前を披露した。','요리사는 능숙한 칼솜씨로 훌륭한 실력을 보여 주었다.'),
('n1-1458','2026-10-27','負債','ふさい','부채; 갚아야 할 채무','企業・個人などが他者に対して返済・支払いの義務を負っている金銭上の債務。','事業拡大のために借入金が増え、会社の負債も大きくなった。','사업 확대를 위해 차입금이 늘어 회사의 부채도 커졌다.'),
('n1-1461','2026-10-27','模索','もさく','모색; 해결책을 찾아봄','はっきりした答えがない中で、方法・方向・解決策などを試しながら探すこと。','会社は新しい収益モデルを模索している。','회사는 새로운 수익 모델을 모색하고 있다.'),
('n1-1472','2026-10-27','内乱','ないらん','내란; 국내의 무력 충돌','一つの国内で、政府・勢力・集団同士が武力を用いて争う大規模な紛争。','長期化した内乱によって、多くの住民が国外へ避難した。','장기화된 내란으로 많은 주민이 국외로 피난했다.'),
('n1-1480','2026-10-27','見合い','みあい','맞선; 중매를 통한 만남','結婚相手を探す目的で、第三者の紹介によって男女が会うこと。','祖父母は親戚の紹介で見合いをし、その後結婚したそうだ。','조부모님은 친척 소개로 맞선을 보고 그 후 결혼했다고 한다.'),
('n1-1483','2026-10-27','土俵','どひょう','도효; 스모 경기장; 비유적으로 활동 무대','相撲を取る円形の競技場。また比喩的に、競争・議論・活動が行われる場。','価格だけで競うのではなく、品質という土俵で勝負したい。','가격만으로 경쟁하지 않고 품질이라는 무대에서 승부하고 싶다.'),
('n1-1486','2026-10-27','手際','てぎわ','솜씨; 일처리 능숙함','仕事・作業を処理する方法や、その進め方の上手さ。','経験豊富な担当者は、トラブルにも手際よく対応した。','경험 많은 담당자는 문제에도 능숙하게 대응했다.'),
('n1-1498','2026-10-27','手引き','てびき','안내; 지침; 안내서','方法・手順・方向などを教えて案内すること。また、そのための説明書・案内書。','初めて利用する人向けに、申請手続きの手引きを公開した。','처음 이용하는 사람을 위해 신청 절차 안내서를 공개했다.'),
('n1-1499','2026-10-27','並列','へいれつ','병렬; 나란히 배치함','複数のものを同じ段階・位置関係で並べること。コンピュータでは複数の処理を同時に進める意味でも使う。','処理時間を短縮するため、独立した作業を並列で実行する。','처리 시간을 줄이기 위해 독립된 작업을 병렬로 실행한다.'),
('n1-1509','2026-10-27','刑罰','けいばつ','형벌','犯罪を犯した者に対し、法律に基づいて国家が科す罰。','刑罰の重さは法律と裁判によって決定される。','형벌의 무게는 법률과 재판에 의해 결정된다.'),
('n1-1512','2026-10-27','鉱業','こうぎょう','광업','鉱石・石炭・石油などの地下資源を採掘・加工する産業。','この地域は長年、鉱業によって経済を支えてきた。','이 지역은 오랫동안 광업으로 경제를 지탱해 왔다.'),
('n1-1513','2026-10-27','付録','ふろく','부록; 별첨','本・雑誌などの本文に追加して付ける資料・記事・物品。','詳しい統計資料は報告書の付録にまとめられている。','자세한 통계 자료는 보고서 부록에 정리되어 있다.'),
('n1-1520','2026-10-27','語句','ごく','어구; 단어나 짧은 표현','文章を構成する単語や短い句・表現。','専門的な語句には注釈を付け、初めて読む人にも分かるようにした。','전문적인 어구에는 주석을 달아 처음 읽는 사람도 이해할 수 있게 했다.'),
('n1-1533','2026-10-27','親善','しんぜん','친선; 우호 증진','国・団体・人どうしが互いに親しみ、友好的な関係を深めること。','両国の学生による親善交流会が毎年開かれている。','양국 학생들의 친선 교류회가 매년 열리고 있다.'),
('n1-1540','2026-10-28','模倣','もほう','모방; 흉내 냄','他人の行動・作品・方法などをまねて同じようにすること。','成功例を単純に模倣するだけでは、同じ成果が出るとは限らない。','성공 사례를 단순히 모방하기만 해서는 같은 성과가 나온다고 할 수 없다.'),
('n1-1546','2026-10-28','熱意','ねつい','열의; 열정','物事を成し遂げようとする強い意欲・情熱。','経験は少なくても、学ぶ熱意のある人を採用したい。','경험이 적더라도 배우려는 열의가 있는 사람을 채용하고 싶다.'),
('n1-1548','2026-10-28','迫害','はくがい','박해; 탄압','権力・社会的立場などを利用して、特定の人々を継続的に苦しめたり排除したりすること。','宗教や民族を理由とする迫害から逃れ、多くの人が国外へ移った。','종교나 민족을 이유로 한 박해를 피해 많은 사람이 국외로 이주했다.'),
('n1-1549','2026-10-28','元首','げんしゅ','국가 원수','国家を代表する最高位の公的地位にある者。制度により大統領・国王など形態は異なる。','式典には各国の元首や政府代表が出席した。','식전에는 각국의 국가 원수와 정부 대표가 참석했다.'),
('n1-1557','2026-10-28','日取り','ひどり','날짜; 일정 날짜','行事・会議・結婚式などを行うために決めた日。','関係者の予定を確認して、式典の日取りを決めた。','관계자들의 일정을 확인해 식전 날짜를 정했다.'),
('n1-1561','2026-10-28','戦災','せんさい','전재; 전쟁으로 인한 재해','戦争によって人命・建物・財産などが受ける災害・被害。','この地域には戦災を免れた古い建物が今も残っている。','이 지역에는 전쟁 피해를 피한 오래된 건물이 지금도 남아 있다.'),
('n1-1565','2026-10-28','海運','かいうん','해운','船を使って旅客・貨物を海上輸送すること。また、その産業。','国際貿易の多くは海運によって支えられている。','국제 무역의 많은 부분은 해운에 의해 뒷받침되고 있다.'),
('n1-1566','2026-10-28','満場','まんじょう','장내 전체; 참석자 전원','会場にいる人全員、または会場全体。『満場一致』などの形でよく用いる。','提案は満場一致で可決された。','제안은 만장일치로 가결되었다.'),
('n1-1572','2026-10-28','漁船','ぎょせん','어선; 고기잡이배','魚介類をとる漁業のために使う船。','早朝、港から多くの漁船が一斉に出港した。','이른 아침 항구에서 많은 어선이 일제히 출항했다.'),
('n1-1573','2026-10-28','天災','てんさい','천재; 자연재해','地震・台風・洪水・干ばつなど、自然現象によって起こる災害。','天災による損害を完全に防ぐことは難しいが、備えはできる。','자연재해로 인한 피해를 완전히 막기는 어렵지만 대비는 할 수 있다.'),
('n1-1574','2026-10-28','比重','ひじゅう','비중; 중요도','物理では基準物質に対する密度の比。比喩的には、全体の中で占める重要さ・割合。','今年は新規開発より既存サービスの改善に比重を置く。','올해는 신규 개발보다 기존 서비스 개선에 비중을 둔다.'),
('n1-1576','2026-10-28','分業','ぶんぎょう','분업','一つの仕事を複数の人・組織で役割ごとに分けて行うこと。','設計と実装を適切に分業することで、作業効率が上がった。','설계와 구현을 적절히 분업해 작업 효율이 높아졌다.'),
('n1-1577','2026-10-28','拡散','かくさん','확산; 퍼짐','物質・情報・影響などが広い範囲へ散って広がること。','誤った情報がSNSで急速に拡散した。','잘못된 정보가 SNS에서 빠르게 확산되었다.'),
('n1-1594','2026-10-28','林業','りんぎょう','임업','森林を育成・管理し、木材などの資源を生産・利用する産業。','担い手不足は地域の林業が抱える大きな課題だ。','인력 부족은 지역 임업이 안고 있는 큰 과제다.'),
('n1-1597','2026-10-28','海流','かいりゅう','해류','海水が一定の方向・速度で大規模に流れる現象。','海流の変化は魚の分布や気候にも影響を与える。','해류 변화는 물고기 분포와 기후에도 영향을 준다.'),
('n1-1603','2026-10-28','許容','きょよう','허용; 용인','一定の範囲・条件の中で認め、受け入れること。','この装置は数ミリ程度の誤差までなら許容できる。','이 장치는 수 밀리미터 정도의 오차까지는 허용할 수 있다.'),
('n1-1604','2026-10-28','浪費','ろうひ','낭비; 허비','金銭・時間・資源などを、必要のないことにむだに使うこと。','会議の目的を明確にしないと、参加者の時間を浪費することになる。','회의 목적을 명확히 하지 않으면 참가자들의 시간을 낭비하게 된다.'),
('n1-1605','2026-10-28','採集','さいしゅう','채집','研究・観察などのため、植物・昆虫・鉱物などを集めること。','研究者は山中で植物の標本を採集した。','연구자는 산속에서 식물 표본을 채집했다.'),
('n1-1607','2026-10-28','根回し','ねまわし','사전 조율; 물밑 작업','計画・提案を円滑に進めるため、正式な決定の前に関係者へ説明し、理解・同意を得ておくこと。','大きな制度変更なので、会議の前に関係部署へ根回しをしておいた。','큰 제도 변경이라 회의 전에 관계 부서와 사전 조율을 해 두었다.'),
('n1-1611','2026-10-28','加味','かみ','가미; 요소를 더해 고려함','ある要素を付け加えること。特に、判断・計画などに別の事情を取り入れて考えること。','経験年数だけでなく、実績や適性も加味して人員を配置する。','경력 연수뿐 아니라 실적과 적성도 가미해 인원을 배치한다.');
INSERT INTO japanese_words(word,reading,meaning_ko,meaning_ja,jlpt_level_id,ai_status,note) SELECT s.word,s.reading,s.meaning_ko,s.meaning_ja,(SELECT id FROM jlpt_levels WHERE code='N1'),'reviewed','JLPT N1 batch 2026-10-15..2026-10-28' FROM _n1_b2_words_0100 s WHERE NOT EXISTS (SELECT 1 FROM japanese_words w WHERE w.word=s.word AND w.reading=s.reading AND w.deleted_at IS NULL);
INSERT INTO _n1_b2_map_0100(source_key,word_id) SELECT s.source_key,MIN(w.id) FROM _n1_b2_words_0100 s JOIN japanese_words w ON w.word=s.word AND w.reading=s.reading AND w.deleted_at IS NULL GROUP BY s.source_key;
