INSERT INTO japanese_jlpt_daily_words(session_id,word_id,item_kind) SELECT ds.id,m.word_id,'new' FROM _n1_b2_words_0100 s JOIN _n1_b2_map_0100 m ON m.source_key=s.source_key JOIN japanese_jlpt_daily_sessions ds ON ds.study_date=s.study_date JOIN japanese_jlpt_study_plans p ON p.id=ds.plan_id WHERE p.plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-15','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-0756","prompt":"「対等」の読み方として最も適切なものを選びなさい。","options":["たくみ","ふけいき","いいかげん","たいとう"],"answer":"たいとう","explanationKo":"「対等」는 「たいとう」라고 읽는다. 뜻은 대등함; 동등한 관계이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-15','vocab_question',2,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-0900","prompt":"「所定」の読み方として最も適切なものを選びなさい。","options":["いっきょに","いっそ","しょてい","こうみょう"],"answer":"しょてい","explanationKo":"「所定」는 「しょてい」라고 읽는다. 뜻은 소정; 정해진 바이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-15','vocab_question',3,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-0941","prompt":"「切実」の読み方として最も適切なものを選びなさい。","options":["いちりつ","せつじつ","れいたん","かんい"],"answer":"せつじつ","explanationKo":"「切実」는 「せつじつ」라고 읽는다. 뜻은 절실함; 절박함이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-15','vocab_question',4,'文字・語彙','{"type":"context_fill","wordKey":"n1-1008","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\nこの資格を取得するには、一定期間の実務経験を（　）ことが条件となる。","options":["有する","成り立つ","遮る","引き上げる"],"answer":"有する","explanationKo":"문맥상 「有する」가 가장 자연스럽다. 가지다; 보유하다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-15','vocab_question',5,'文字・語彙','{"type":"context_fill","wordKey":"n1-1060","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n限られた予算を（　）有効に使うかが問われている。","options":["円満","久しい","いっそ","如何に"],"answer":"如何に","explanationKo":"문맥상 「如何に」가 가장 자연스럽다. 어떻게; 얼마나; 아무리 ~해도라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-15','vocab_question',6,'文字・語彙','{"type":"context_fill","wordKey":"n1-1159","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n個人情報を無断で公開する行為は社内規定に（　）。","options":["受け継ぐ","生かす","反する","貶す"],"answer":"反する","explanationKo":"문맥상 「反する」가 가장 자연스럽다. 반하다; 어긋나다; 위반하다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-15','vocab_question',7,'文字・語彙','{"type":"context_fill","wordKey":"n1-1237","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n記録を（　）と、問題は数か月前から少しずつ発生していた。","options":["仰ぐ","辿る","取り締まる","深める"],"answer":"辿る","explanationKo":"문맥상 「辿る」가 가장 자연스럽다. 더듬어 가다; 따라가다; 추적하다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-15','vocab_question',8,'文字・語彙','{"type":"context_fill","wordKey":"n1-1249","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\nまず（　）版を公開し、利用状況を見ながら機能を追加する。","options":["簡易","無念","自ずから","冷淡"],"answer":"簡易","explanationKo":"문맥상 「簡易」가 가장 자연스럽다. 간이; 간단한 방식라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-15','vocab_question',9,'文字・語彙','{"type":"context_fill","wordKey":"n1-1256","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n議論を重ねることで互いの理解を（　）ことができた。","options":["諮る","試みる","打ち込む","深める"],"answer":"深める","explanationKo":"문맥상 「深める」가 가장 자연스럽다. 깊게 하다; 심화하다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-15','vocab_question',10,'文字・語彙','{"type":"context_fill","wordKey":"n1-1263","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\nこの画面では個人情報を（　）ため、権限管理が必要だ。","options":["労る","上回る","取り扱う","生かす"],"answer":"取り扱う","explanationKo":"문맥상 「取り扱う」가 가장 자연스럽다. 취급하다; 다루다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-15','vocab_question',11,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-1014","prompt":"「答え・説明を求める。また、責任・価値・是非などを問題として取り上げる。」という意味に最も近い語を選びなさい。","options":["捗る","問う","手掛ける","高まる"],"answer":"問う","explanationKo":"「問う」의 핵심 의미는 묻다; 따지다; 문제 삼다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-15','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-1181","prompt":"「数値・程度・実績などが基準・比較対象より高くなる。」という意味に最も近い語を選びなさい。","options":["上回る","賄う","乱れる","担う"],"answer":"上回る","explanationKo":"「上回る」의 핵심 의미는 웃돌다; 상회하다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-15','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-1187","prompt":"「時間・労力・金銭などを、ある目的のために使う。」という意味に最も近い語を選びなさい。","options":["遠ざかる","結び付く","傾ける","費やす"],"answer":"費やす","explanationKo":"「費やす」의 핵심 의미는 쓰다; 들이다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-15','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-1215","prompt":"「前の世代・担当者などから、財産・伝統・技術・精神・仕事などを引き継ぐ。」という意味に最も近い語を選びなさい。","options":["志す","貶す","受け継ぐ","値する"],"answer":"受け継ぐ","explanationKo":"「受け継ぐ」의 핵심 의미는 이어받다; 계승하다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-15','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-1281","prompt":"「物を上へ引き上げる。また、価格・水準・地位などを高くする。文脈によってはその場から引き払う意味にも用いる。」という意味に最も近い語を選びなさい。","options":["反する","引き上げる","担う","賄う"],"answer":"引き上げる","explanationKo":"「引き上げる」의 핵심 의미는 끌어올리다; 인상하다; 철수하다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-15','grammar',1,'〜あまり','{"pattern":"〜あまり","meaningKo":"너무 〜한 나머지","explanation":"〜あまり는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"結果を急ぐあまり、確認すべき手順を省いてしまった。","ko":"문맥에서 너무 〜한 나머지의 의미로 쓰였다."},{"ja":"緊張のあまり、質問にうまく答えられなかった。","ko":"이 문장도 너무 〜한 나머지의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-15','grammar',2,'〜あって','{"pattern":"〜あって","meaningKo":"〜이기에; 〜가 있어서","explanation":"〜あって는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"長年の信頼関係あって、今回の協力が実現した。","ko":"문맥에서 〜이기에; 〜가 있어서의 의미로 쓰였다."},{"ja":"皆の支えあっての成果だと、本人は語った。","ko":"이 문장도 〜이기에; 〜가 있어서의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-15','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n結果を急ぐ（　）、確認すべき手順を省いてしまった。","options":["〜あまり","〜ようと","〜が早いか","〜そびれる"],"answer":"〜あまり","explanationKo":"문맥상 너무 〜한 나머지를 나타내는 「〜あまり」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-15','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n長年の信頼関係（　）、今回の協力が実現した。","options":["〜得る","〜からある","〜たるもの","〜あって"],"answer":"〜あって","explanationKo":"문맥상 〜이기에; 〜가 있어서를 나타내는 「〜あって」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-15','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n採用するか否かは、面接の内容（　）決まる。","options":["〜きらいがある","〜たとたん","〜いかんだ","〜かたがた"],"answer":"〜いかんだ","explanationKo":"문맥상 〜에 달려 있다를 나타내는 「〜いかんだ」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-15','reading',1,'例外を扱う基準','{"passage":"規則に例外を設けることには、予測できない事情にも対応できることという利点がある。しかし、利点だけを見て進めると、例外を増やしすぎると基準が曖昧になること。そのため、実施する側は何を目的にするのかを共有し、途中で生じた問題も記録する必要がある。重要なのは、最初の方法を守り続けることではなく、状況を確かめながら目的と判断の経緯を記録して適用することことである。","questions":[{"prompt":"「例外を扱う基準」で筆者が最も重視していることは何か。","options":["目的と判断の経緯を記録して適用すること","最初の方法を変更しないこと","速度だけを優先すること","問題を記録しないこと"],"answer":"目的と判断の経緯を記録して適用すること","explanationKo":"본문에서는 상황을 확인하면서 目的と判断の経緯を記録して適用すること 것이 중요하다고 설명한다."},{"prompt":"本文で注意すべき点として挙げられているものは何か。","options":["例外を増やしすぎると基準が曖昧になること","利点が必ずなくなること","説明が不要になること","利用者が減ること"],"answer":"例外を増やしすぎると基準が曖昧になること","explanationKo":"장점만 보고 진행하면 例外を増やしすぎると基準が曖昧になること 수 있다고 지적한다."},{"prompt":"本文の内容と合うものはどれか。","options":["予測できない事情にも対応できること","目的を共有する必要はない","途中の問題は隠すべきだ","判断は最初に一度だけ行うべきだ"],"answer":"予測できない事情にも対応できること","explanationKo":"規則に例外を設けること에는 予測できない事情にも対応できること라는 장점이 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-16','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-1417","prompt":"「漏らす」の読み方として最も適切なものを選びなさい。","options":["もらす","はかどる","とう","なりたつ"],"answer":"もらす","explanationKo":"「漏らす」는 「もらす」라고 읽는다. 뜻은 누설하다; 빠뜨리다; 새게 하다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
