INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-16','vocab_question',4,'文字・語彙','{"type":"context_fill","wordKey":"n1-1508","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n決勝直前のけがで出場を断念することになり、本人は（　）をにじませた。","options":["ややこしい","無念","いい加減","所定"],"answer":"無念","explanationKo":"문맥상 「無念」가 가장 자연스럽다. 분함; 원통함; 유감스러움라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
