INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-16','vocab_question',7,'文字・語彙','{"type":"context_fill","wordKey":"n1-1657","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n細かい規則が多すぎると、現場は（　）に感じる。","options":["区々","簡易","窮屈","空しい"],"answer":"窮屈","explanationKo":"문맥상 「窮屈」가 가장 자연스럽다. 비좁음; 답답함; 제약이 많음라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
