INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-16','vocab_question',9,'文字・語彙','{"type":"context_fill","wordKey":"n1-1675","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n（　）に作られた偽サイトは本物と見分けにくい。","options":["巧妙","賢明","不景気","いい加減"],"answer":"巧妙","explanationKo":"문맥상 「巧妙」가 가장 자연스럽다. 교묘함; 정교하고 능숙함라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
