INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-16','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-1714","prompt":"「事情・仕組み・関係などが複雑で、理解・処理しにくい。」という意味に最も近い語を選びなさい。","options":["あべこべ","簡易","ややこしい","空しい"],"answer":"ややこしい","explanationKo":"「ややこしい」의 핵심 의미는 복잡하고 까다롭다; 헷갈리다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-16','grammar',1,'〜いかんだ','{"pattern":"〜いかんだ","meaningKo":"〜에 달려 있다","explanation":"〜いかんだ는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"計画が成功するかどうかは、準備いかんだ。","ko":"문맥에서 〜에 달려 있다의 의미로 쓰였다."},{"ja":"採用するか否かは、面接の内容いかんで決まる。","ko":"이 문장도 〜에 달려 있다의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-16','grammar',2,'〜以上は','{"pattern":"〜以上は","meaningKo":"〜한 이상은","explanation":"〜以上は는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"引き受けた以上は、最後まで責任を果たしたい。","ko":"문맥에서 〜한 이상은의 의미로 쓰였다."},{"ja":"規則を定めた以上は、例外なく守る必要がある。","ko":"이 문장도 〜한 이상은의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-16','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n計画が成功するかどうかは、準備（　）。","options":["〜かたがた","〜きらいがある","〜たとたん","〜いかんだ"],"answer":"〜いかんだ","explanationKo":"문맥상 〜에 달려 있다를 나타내는 「〜いかんだ」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-16','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n引き受けた（　）、最後まで責任を果たしたい。","options":["〜極まる","〜つつある","〜以上は","〜限りだ"],"answer":"〜以上は","explanationKo":"문맥상 〜한 이상은를 나타내는 「〜以上は」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-16','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n誰が反対し（　）、必要な改革は進めるべきだ。","options":["〜てしかるべき","〜ようが","〜かねない","〜ごとき"],"answer":"〜ようが","explanationKo":"문맥상 아무리 〜해도를 나타내는 「〜ようが」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-16','reading',1,'情報を更新する責任','{"passage":"一度公表した情報を更新することには、利用者が古い情報で判断するのを防げることという利点がある。しかし、利点だけを見て進めると、修正理由が示されなければ信頼を損なうこと。そのため、実施する側は何を目的にするのかを共有し、途中で生じた問題も記録する必要がある。重要なのは、最初の方法を守り続けることではなく、状況を確かめながら変更点と理由を分かる形で伝えることことである。","questions":[{"prompt":"「情報を更新する責任」で筆者が最も重視していることは何か。","options":["変更点と理由を分かる形で伝えること","最初の方法を変更しないこと","速度だけを優先すること","問題を記録しないこと"],"answer":"変更点と理由を分かる形で伝えること","explanationKo":"본문에서는 상황을 확인하면서 変更点と理由を分かる形で伝えること 것이 중요하다고 설명한다."},{"prompt":"本文で注意すべき点として挙げられているものは何か。","options":["修正理由が示されなければ信頼を損なうこと","利点が必ずなくなること","説明が不要になること","利用者が減ること"],"answer":"修正理由が示されなければ信頼を損なうこと","explanationKo":"장점만 보고 진행하면 修正理由が示されなければ信頼を損なうこと 수 있다고 지적한다."},{"prompt":"本文の内容と合うものはどれか。","options":["利用者が古い情報で判断するのを防げること","目的を共有する必要はない","途中の問題は隠すべきだ","判断は最初に一度だけ行うべきだ"],"answer":"利用者が古い情報で判断するのを防げること","explanationKo":"一度公表した情報を更新すること에는 利用者が古い情報で判断するのを防げること라는 장점이 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-17','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-1858","prompt":"「生かす」の読み方として最も適切なものを選びなさい。","options":["つかさどる","いかす","いたわる","うわまわる"],"answer":"いかす","explanationKo":"「生かす」는 「いかす」라고 읽는다. 뜻은 살리다; 활용하다; 발휘하게 하다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
