INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-17','vocab_question',3,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-1933","prompt":"「値する」の読み方として最も適切なものを選びなさい。","options":["いたわる","もらす","みだれる","あたいする"],"answer":"あたいする","explanationKo":"「値する」는 「あたいする」라고 읽는다. 뜻은 ~할 가치가 있다; ~할 만하다; 값하다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-17','vocab_question',4,'文字・語彙','{"type":"context_fill","wordKey":"n1-2014","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\nこの条件に（　）人だけが申請できる。","options":["傾ける","裁く","当てはまる","結び付く"],"answer":"当てはまる","explanationKo":"문맥상 「当てはまる」가 가장 자연스럽다. 해당하다; 들어맞다; 적용되다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
