INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-17','vocab_question',6,'文字・語彙','{"type":"context_fill","wordKey":"n1-2095","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n料金を（　）千円に設定した。","options":["一律","怠慢","簡易","自ずから"],"answer":"一律","explanationKo":"문맥상 「一律」가 가장 자연스럽다. 일률적임; 획일적임; 동일하게라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-17','vocab_question',7,'文字・語彙','{"type":"context_fill","wordKey":"n1-2126","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n夜更かしは体に（　）。","options":["侵す","経る","漏らす","障る"],"answer":"障る","explanationKo":"문맥상 「障る」가 가장 자연스럽다. 지장을 주다; 해가 되다; 방해하다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-17','vocab_question',8,'文字・語彙','{"type":"context_fill","wordKey":"n1-2204","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n話し合いによって問題は（　）に解決した。","options":["窮屈","切実","円満","空しい"],"answer":"円満","explanationKo":"문맥상 「円満」가 가장 자연스럽다. 원만함; 화목함라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-17','vocab_question',9,'文字・語彙','{"type":"context_fill","wordKey":"n1-2230","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n重要な案件なので専門家に（　）ことにした。","options":["障る","諮る","有する","辿る"],"answer":"諮る","explanationKo":"문맥상 「諮る」가 가장 자연스럽다. 상의하다; 자문을 구하다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-17','vocab_question',10,'文字・語彙','{"type":"context_fill","wordKey":"n1-2274","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n（　）の影響で売り上げが大きく落ち込んだ。","options":["不景気","如何に","冷淡","無念"],"answer":"不景気","explanationKo":"문맥상 「不景気」가 가장 자연스럽다. 불경기; 경기 침체라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-17','vocab_question',11,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-1942","prompt":"「物事・関係・条件などが成立する。また、複数の要素から構成される、あるいは生活・事業などが維持できる。」という意味に最も近い語を選びなさい。","options":["問う","生かす","弛む","成り立つ"],"answer":"成り立つ","explanationKo":"「成り立つ」의 핵심 의미는 성립하다; 이루어지다; 구성되다; 유지되다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-17','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-1950","prompt":"「目上の者などが、地位・資格・物・知識・技術などを与える。」という意味に最も近い語を選びなさい。","options":["齎らす","仰ぐ","授ける","禁ずる"],"answer":"授ける","explanationKo":"「授ける」의 핵심 의미는 주다; 수여하다; 전수하다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-17','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-1980","prompt":"「ある仕事・機能などを責任を持って管理する。」という意味に最も近い語を選びなさい。","options":["手掛ける","司る","裁く","遮る"],"answer":"司る","explanationKo":"「司る」의 핵심 의미는 관장하다; 담당하다; 지배하다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-17','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-2111","prompt":"「物を斜めにする。また、注意・力・心などを一つの対象に集中する。」という意味に最も近い語を選びなさい。","options":["傾ける","即する","受け継ぐ","司る"],"answer":"傾ける","explanationKo":"「傾ける」의 핵심 의미는 기울이다; 집중하다; 쏟다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-17','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-2125","prompt":"「整っていたもの・秩序・心などが崩れて不規則になる。」という意味に最も近い語を選びなさい。","options":["生かす","絶つ","費やす","乱れる"],"answer":"乱れる","explanationKo":"「乱れる」의 핵심 의미는 흐트러지다; 어지러워지다; 혼란해지다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-17','grammar',1,'〜ようが','{"pattern":"〜ようが","meaningKo":"아무리 〜해도","explanation":"〜ようが는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"どれほど説明しようが、事実そのものは変わらない。","ko":"문맥에서 아무리 〜해도의 의미로 쓰였다."},{"ja":"誰が反対しようが、必要な改革は進めるべきだ。","ko":"이 문장도 아무리 〜해도의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-17','grammar',2,'〜ようと','{"pattern":"〜ようと","meaningKo":"설령 〜하더라도","explanation":"〜ようと는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"事情がどうであろうと、期限は守らなければならない。","ko":"문맥에서 설령 〜하더라도의 의미로 쓰였다."},{"ja":"どんなに困難であろうと、方法を探し続ける。","ko":"이 문장도 설령 〜하더라도의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
