INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-17','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\nこの装置なら、微小な変化も検出し（　）。","options":["〜得る","〜が早いか","〜ずくめ","〜ときたら"],"answer":"〜得る","explanationKo":"문맥상 〜할 수 있다를 나타내는 「〜得る」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-17','reading',1,'役割分担の見直し','{"passage":"仕事の役割を分けることには、専門性を生かして負担を調整できることという利点がある。しかし、利点だけを見て進めると、担当の境界だけを守ると連携が弱くなること。そのため、実施する側は何を目的にするのかを共有し、途中で生じた問題も記録する必要がある。重要なのは、最初の方法を守り続けることではなく、状況を確かめながら目的を共有した上で境界を見直すことことである。","questions":[{"prompt":"「役割分担の見直し」で筆者が最も重視していることは何か。","options":["目的を共有した上で境界を見直すこと","最初の方法を変更しないこと","速度だけを優先すること","問題を記録しないこと"],"answer":"目的を共有した上で境界を見直すこと","explanationKo":"본문에서는 상황을 확인하면서 目的を共有した上で境界を見直すこと 것이 중요하다고 설명한다."},{"prompt":"本文で注意すべき点として挙げられているものは何か。","options":["担当の境界だけを守ると連携が弱くなること","利点が必ずなくなること","説明が不要になること","利用者が減ること"],"answer":"担当の境界だけを守ると連携が弱くなること","explanationKo":"장점만 보고 진행하면 担当の境界だけを守ると連携が弱くなること 수 있다고 지적한다."},{"prompt":"本文の内容と合うものはどれか。","options":["専門性を生かして負担を調整できること","目的を共有する必要はない","途中の問題は隠すべきだ","判断は最初に一度だけ行うべきだ"],"answer":"専門性を生かして負担を調整できること","explanationKo":"仕事の役割を分けること에는 専門性を生かして負担を調整できること라는 장점이 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-18','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-2387","prompt":"「揺さぶる」の読み方として最も適切なものを選びなさい。","options":["ついやす","つかさどる","ゆさぶる","たるむ"],"answer":"ゆさぶる","explanationKo":"「揺さぶる」는 「ゆさぶる」라고 읽는다. 뜻은 세게 흔들다; 뒤흔들다; 충격을 주다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-18','vocab_question',2,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-2398","prompt":"「貶す」の読み方として最も適切なものを選びなさい。","options":["うわまわる","けなす","たかまる","いたわる"],"answer":"けなす","explanationKo":"「貶す」는 「けなす」라고 읽는다. 뜻은 헐뜯다; 깎아내리다; 폄하하다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-18','vocab_question',3,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-2465","prompt":"「自ずから」の読み方として最も適切なものを選びなさい。","options":["おのずから","みっともない","こうみょう","たいとう"],"answer":"おのずから","explanationKo":"「自ずから」는 「おのずから」라고 읽는다. 뜻은 저절로; 자연히; 자연스럽게이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-18','vocab_question',4,'文字・語彙','{"type":"context_fill","wordKey":"n1-2496","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n日々の努力が最終的な成果に（　）。","options":["賄う","乱れる","図る","結び付く"],"answer":"結び付く","explanationKo":"문맥상 「結び付く」가 가장 자연스럽다. 결부되다; 연결되다; 관련되다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-18','vocab_question',5,'文字・語彙','{"type":"context_fill","wordKey":"n1-2584","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\nイベント費用は参加費で（　）予定だ。","options":["貶す","傾ける","賄う","志す"],"answer":"賄う","explanationKo":"문맥상 「賄う」가 가장 자연스럽다. 충당하다; 마련하다; 식사를 제공하다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-18','vocab_question',6,'文字・語彙','{"type":"context_fill","wordKey":"n1-2632","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n努力が全く評価されず、（　）気持ちになった。","options":["巧妙","空しい","いっそ","一挙に"],"answer":"空しい","explanationKo":"문맥상 「空しい」가 가장 자연스럽다. 허무하다; 헛되다; 공허하다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-18','vocab_question',7,'文字・語彙','{"type":"context_fill","wordKey":"n1-2637","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n悪い習慣を（　）ために生活を見直した。","options":["絶つ","侵す","試みる","富む"],"answer":"絶つ","explanationKo":"문맥상 「絶つ」가 가장 자연스럽다. 끊다; 단절하다; 끊어 버리다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-18','vocab_question',8,'文字・語彙','{"type":"context_fill","wordKey":"n1-2718","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n人前でそんな言い争いをするのは（　）。","options":["怠慢","如何に","自ずから","見っともない"],"answer":"見っともない","explanationKo":"문맥상 「見っともない」가 가장 자연스럽다. 보기 흉하다; 창피하다; 꼴사납다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-18','vocab_question',9,'文字・語彙','{"type":"context_fill","wordKey":"n1-2842","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n忙しい時ほど互いの体を（　）ことが大切だ。","options":["取り扱う","取り締まる","労る","反する"],"answer":"労る","explanationKo":"문맥상 「労る」가 가장 자연스럽다. 위로하다; 돌보다; 배려하다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-18','vocab_question',10,'文字・語彙','{"type":"context_fill","wordKey":"n1-2844","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n新機能を（　）公開した。","options":["所定","一挙に","区々","怠慢"],"answer":"一挙に","explanationKo":"문맥상 「一挙に」가 가장 자연스럽다. 단숨에; 한꺼번에; 일거에라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-18','vocab_question',11,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-2513","prompt":"「仕事・制作などを自ら担当し、取り組む。また、世話や管理をする。」という意味に最も近い語を選びなさい。","options":["手掛ける","引き上げる","富む","侵す"],"answer":"手掛ける","explanationKo":"「手掛ける」의 핵심 의미는 다루다; 맡아서 하다; 직접 관여하다; 제작하다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-18','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-2626","prompt":"「進行・視線・光・音などを途中で妨げ、通らないようにする。」という意味に最も近い語を選びなさい。","options":["捗る","問う","生かす","遮る"],"answer":"遮る","explanationKo":"「遮る」의 핵심 의미는 가로막다; 막다; 차단하다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-18','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-2640","prompt":"「事実・基準・状況などに合うようにする。基づく。」という意味に最も近い語を選びなさい。","options":["乱れる","齎らす","即する","漏らす"],"answer":"即する","explanationKo":"「即する」의 핵심 의미는 부합하다; 따르다; ~에 입각하다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-18','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-2747","prompt":"「仕事・作業などが順調に進む。」という意味に最も近い語を選びなさい。","options":["賄う","捗る","傾ける","裁く"],"answer":"捗る","explanationKo":"「捗る」의 핵심 의미는 진척되다; 순조롭게 진행되다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-18','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-2780","prompt":"「それぞれ異なっていて、統一されていないさま。」という意味に最も近い語を選びなさい。","options":["区々","ややこしい","窮屈","一挙に"],"answer":"区々","explanationKo":"「区々」의 핵심 의미는 제각각; 가지각색; 일정하지 않음이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-18','grammar',1,'〜得る','{"pattern":"〜得る","meaningKo":"〜할 수 있다","explanation":"〜得る는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"その判断は、状況によっては十分起こり得る。","ko":"문맥에서 〜할 수 있다의 의미로 쓰였다."},{"ja":"この装置なら、微小な変化も検出し得る。","ko":"이 문장도 〜할 수 있다의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-18','grammar',2,'〜かたがた','{"pattern":"〜かたがた","meaningKo":"〜하는 겸","explanation":"〜かたがた는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"ご報告かたがた、日頃のお礼を申し上げます。","ko":"문맥에서 〜하는 겸의 의미로 쓰였다."},{"ja":"近況を伺いかたがた、先生を訪ねた。","ko":"이 문장도 〜하는 겸의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-18','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\nその判断は、状況によっては十分起こり（　）。","options":["〜ときたら","〜得る","〜が早いか","〜ずくめ"],"answer":"〜得る","explanationKo":"문맥상 〜할 수 있다를 나타내는 「〜得る」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
