INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-18','reading',1,'短期の成果と長期の価値','{"passage":"短期の成果を測ることには、進捗を早く把握できることという利点がある。しかし、利点だけを見て進めると、将来の基盤づくりが後回しになること。そのため、実施する側は何を目的にするのかを共有し、途中で生じた問題も記録する必要がある。重要なのは、最初の方法を守り続けることではなく、状況を確かめながら長期の価値も評価の対象に含めることことである。","questions":[{"prompt":"「短期の成果と長期の価値」で筆者が最も重視していることは何か。","options":["長期の価値も評価の対象に含めること","最初の方法を変更しないこと","速度だけを優先すること","問題を記録しないこと"],"answer":"長期の価値も評価の対象に含めること","explanationKo":"본문에서는 상황을 확인하면서 長期の価値も評価の対象に含めること 것이 중요하다고 설명한다."},{"prompt":"本文で注意すべき点として挙げられているものは何か。","options":["将来の基盤づくりが後回しになること","利点が必ずなくなること","説明が不要になること","利用者が減ること"],"answer":"将来の基盤づくりが後回しになること","explanationKo":"장점만 보고 진행하면 将来の基盤づくりが後回しになること 수 있다고 지적한다."},{"prompt":"本文の内容と合うものはどれか。","options":["進捗を早く把握できること","目的を共有する必要はない","途中の問題は隠すべきだ","判断は最初に一度だけ行うべきだ"],"answer":"進捗を早く把握できること","explanationKo":"短期の成果を測ること에는 進捗を早く把握できること라는 장점이 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-19','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-0718","prompt":"「改定」の読み方として最も適切なものを選びなさい。","options":["すいげん","せんさい","はんきょう","かいてい"],"answer":"かいてい","explanationKo":"「改定」는 「かいてい」라고 읽는다. 뜻은 개정; 규정·가격 등을 새로 정함이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
