INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-19','vocab_question',4,'文字・語彙','{"type":"context_fill","wordKey":"n1-0735","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n年度末の（　）に向けて、各部門が経費の確認を進めている。","options":["決算","抽選","不意","鉄鋼"],"answer":"決算","explanationKo":"문맥상 「決算」가 가장 자연스럽다. 결산; 회계 마감라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
