INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-19','vocab_question',11,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0765","prompt":"「ある目的・成果の実現に役立つこと。」という意味に最も近い語を選びなさい。","options":["長官","寄与","加味","責務"],"answer":"寄与","explanationKo":"「寄与」의 핵심 의미는 기여; 공헌이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-19','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0766","prompt":"「複数の数値・データを集めてまとめ、合計や結果を出すこと。」という意味に最も近い語を選びなさい。","options":["集計","財政","訴え","威力"],"answer":"集計","explanationKo":"「集計」의 핵심 의미는 집계; 합산이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-19','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0771","prompt":"「議会・会議などで審議・決定するために提出される案。」という意味に最も近い語を選びなさい。","options":["廃棄","征服","閲覧","議案"],"answer":"議案","explanationKo":"「議案」의 핵심 의미는 의안; 회의 안건이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-19','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0773","prompt":"「会議・議会で審議したうえで、正式に意思を決定すること。」という意味に最も近い語を選びなさい。","options":["海運","変遷","議決","岩石"],"answer":"議決","explanationKo":"「議決」의 핵심 의미는 의결; 결의이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-19','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0776","prompt":"「音が反射して響き返ること。また、出来事・発言などに対して社会から生じる反応。」という意味に最も近い語を選びなさい。","options":["繁栄","反響","寄与","採決"],"answer":"反響","explanationKo":"「反響」의 핵심 의미는 반향; 큰 반응; 울림이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-19','grammar',1,'〜限りだ','{"pattern":"〜限りだ","meaningKo":"더없이 〜하다","explanation":"〜限りだ는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"長年の努力が認められ、うれしい限りだ。","ko":"문맥에서 더없이 〜하다의 의미로 쓰였다."},{"ja":"このような機会をいただき、光栄の限りです。","ko":"이 문장도 더없이 〜하다의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-19','grammar',2,'〜かねない','{"pattern":"〜かねない","meaningKo":"〜할 우려가 있다","explanation":"〜かねない는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"曖昧な説明は、かえって誤解を招きかねない。","ko":"문맥에서 〜할 우려가 있다의 의미로 쓰였다."},{"ja":"小さな不備でも、重大な事故につながりかねない。","ko":"이 문장도 〜할 우려가 있다의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-19','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n長年の努力が認められ、うれしい（　）。","options":["〜限りだ","〜きらいがある","〜そびれる","〜ないまでも"],"answer":"〜限りだ","explanationKo":"문맥상 더없이 〜하다를 나타내는 「〜限りだ」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-19','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n曖昧な説明は、かえって誤解を招き（　）。","options":["〜極まる","〜たるもの","〜あまり","〜かねない"],"answer":"〜かねない","explanationKo":"문맥상 〜할 우려가 있다를 나타내는 「〜かねない」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-19','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n根拠が不十分なため、結論を出し（　）。","options":["〜たとたん","〜あって","〜かねる","〜ごとき"],"answer":"〜かねる","explanationKo":"문맥상 〜하기 어렵다를 나타내는 「〜かねる」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-19','reading',1,'数字の背景を確かめる','{"passage":"数値の変化を見ることには、状況の変化に早く気づけることという利点がある。しかし、利点だけを見て進めると、原因を確認せず結論を急ぐこと。そのため、実施する側は何を目的にするのかを共有し、途中で生じた問題も記録する必要がある。重要なのは、最初の方法を守り続けることではなく、状況を確かめながら現場の事情と合わせて解釈することことである。","questions":[{"prompt":"「数字の背景を確かめる」で筆者が最も重視していることは何か。","options":["現場の事情と合わせて解釈すること","最初の方法を変更しないこと","速度だけを優先すること","問題を記録しないこと"],"answer":"現場の事情と合わせて解釈すること","explanationKo":"본문에서는 상황을 확인하면서 現場の事情と合わせて解釈すること 것이 중요하다고 설명한다."},{"prompt":"本文で注意すべき点として挙げられているものは何か。","options":["原因を確認せず結論を急ぐこと","利点が必ずなくなること","説明が不要になること","利用者が減ること"],"answer":"原因を確認せず結論を急ぐこと","explanationKo":"장점만 보고 진행하면 原因を確認せず結論を急ぐこと 수 있다고 지적한다."},{"prompt":"本文の内容と合うものはどれか。","options":["状況の変化に早く気づけること","目的を共有する必要はない","途中の問題は隠すべきだ","判断は最初に一度だけ行うべきだ"],"answer":"状況の変化に早く気づけること","explanationKo":"数値の変化を見ること에는 状況の変化に早く気づけること라는 장점이 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
