INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-20','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0867","prompt":"「立場・役割にともなって果たすべき責任・義務。」という意味に最も近い語を選びなさい。","options":["責務","清算","動員","救援"],"answer":"責務","explanationKo":"「責務」의 핵심 의미는 책무; 책임과 의무이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-20','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0873","prompt":"「職業について働くこと。また、勤務を開始すること。」という意味に最も近い語を選びなさい。","options":["国交","内乱","天災","就業"],"answer":"就業","explanationKo":"「就業」의 핵심 의미는 취업; 일을 함이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-20','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-0876","prompt":"「金銭上の貸し借り・債権債務などを計算して処理し、関係を終わらせること。」という意味に最も近い語を選びなさい。","options":["反響","降伏","清算","海運"],"answer":"清算","explanationKo":"「清算」의 핵심 의미는 청산; 정산이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-20','grammar',1,'〜かねる','{"pattern":"〜かねる","meaningKo":"〜하기 어렵다","explanation":"〜かねる는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"その件については、今ここでお答えしかねます。","ko":"문맥에서 〜하기 어렵다의 의미로 쓰였다."},{"ja":"根拠が不十分なため、結論を出しかねている。","ko":"이 문장도 〜하기 어렵다의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-20','grammar',2,'〜が早いか','{"pattern":"〜が早いか","meaningKo":"〜하자마자","explanation":"〜が早いか는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"ベルが鳴るが早いか、学生たちは教室を出て行った。","ko":"문맥에서 〜하자마자의 의미로 쓰였다."},{"ja":"知らせを聞くが早いか、彼は現場へ向かった。","ko":"이 문장도 〜하자마자의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-20','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\nその件については、今ここでお答えし（　）。","options":["〜ごとき","〜たとたん","〜あって","〜かねる"],"answer":"〜かねる","explanationKo":"문맥상 〜하기 어렵다를 나타내는 「〜かねる」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-20','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\nベルが鳴る（　）、学生たちは教室を出て行った。","options":["〜つつある","〜いかんだ","〜が早いか","〜始末だ"],"answer":"〜が早いか","explanationKo":"문맥상 〜하자마자를 나타내는 「〜が早いか」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-20','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\nこの資料には百ページ（　）詳細な記録が残っている。","options":["〜以上は","〜からある","〜ずくめ","〜てしかるべき"],"answer":"〜からある","explanationKo":"문맥상 무려 〜이나 되는를 나타내는 「〜からある」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-20','reading',1,'相談しやすい組織','{"passage":"相談の機会を用意することには、問題を早い段階で共有できることという利点がある。しかし、利点だけを見て進めると、結論を代わりに決める場になること。そのため、実施する側は何を目的にするのかを共有し、途中で生じた問題も記録する必要がある。重要なのは、最初の方法を守り続けることではなく、状況を確かめながら本人が判断できる情報を整えることことである。","questions":[{"prompt":"「相談しやすい組織」で筆者が最も重視していることは何か。","options":["本人が判断できる情報を整えること","最初の方法を変更しないこと","速度だけを優先すること","問題を記録しないこと"],"answer":"本人が判断できる情報を整えること","explanationKo":"본문에서는 상황을 확인하면서 本人が判断できる情報を整えること 것이 중요하다고 설명한다."},{"prompt":"本文で注意すべき点として挙げられているものは何か。","options":["結論を代わりに決める場になること","利点が必ずなくなること","説明が不要になること","利用者が減ること"],"answer":"結論を代わりに決める場になること","explanationKo":"장점만 보고 진행하면 結論を代わりに決める場になること 수 있다고 지적한다."},{"prompt":"本文の内容と合うものはどれか。","options":["問題を早い段階で共有できること","目的を共有する必要はない","途中の問題は隠すべきだ","判断は最初に一度だけ行うべきだ"],"answer":"問題を早い段階で共有できること","explanationKo":"相談の機会を用意すること에는 問題を早い段階で共有できること라는 장점이 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
