INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-21','vocab_question',7,'文字・語彙','{"type":"context_fill","wordKey":"n1-0919","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n金額を現在の為替レートで円に（　）すると、およそ十万円になる。","options":["繊維","首脳","願書","換算"],"answer":"換算","explanationKo":"문맥상 「換算」가 가장 자연스럽다. 환산; 다른 단위로 바꾸어 계산함라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
