INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-21','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\nこの議論は感情的になり（　）。","options":["〜ようが","〜きらいがある","〜すら","〜ではあるまいし"],"answer":"〜きらいがある","explanationKo":"문맥상 〜하는 경향이 있다를 나타내는 「〜きらいがある」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-21','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n安全を軽視するとは、危険（　）行為だ。","options":["〜極まる","〜そびれる","〜ときたら","〜ようと"],"answer":"〜極まる","explanationKo":"문맥상 극히 〜하다를 나타내는 「〜極まる」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-21','reading',1,'手順を簡潔にする','{"passage":"手順を簡潔にすることには、見落としや負担を減らせることという利点がある。しかし、利点だけを見て進めると、必要な確認まで省いてしまうこと。そのため、実施する側は何を目的にするのかを共有し、途中で生じた問題も記録する必要がある。重要なのは、最初の方法を守り続けることではなく、状況を確かめながら残す確認と省く作業を区別することことである。","questions":[{"prompt":"「手順を簡潔にする」で筆者が最も重視していることは何か。","options":["残す確認と省く作業を区別すること","最初の方法を変更しないこと","速度だけを優先すること","問題を記録しないこと"],"answer":"残す確認と省く作業を区別すること","explanationKo":"본문에서는 상황을 확인하면서 残す確認と省く作業を区別すること 것이 중요하다고 설명한다."},{"prompt":"本文で注意すべき点として挙げられているものは何か。","options":["必要な確認まで省いてしまうこと","利点が必ずなくなること","説明が不要になること","利用者が減ること"],"answer":"必要な確認まで省いてしまうこと","explanationKo":"장점만 보고 진행하면 必要な確認まで省いてしまうこと 수 있다고 지적한다."},{"prompt":"本文の内容と合うものはどれか。","options":["見落としや負担を減らせること","目的を共有する必要はない","途中の問題は隠すべきだ","判断は最初に一度だけ行うべきだ"],"answer":"見落としや負担を減らせること","explanationKo":"手順を簡潔にすること에는 見落としや負担を減らせること라는 장점이 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-22','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-1015","prompt":"「根拠」の読み方として最も適切なものを選びなさい。","options":["しんこう","しんこく","こんきょ","ひれい"],"answer":"こんきょ","explanationKo":"「根拠」는 「こんきょ」라고 읽는다. 뜻은 근거; 논거이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
