INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-22','vocab_question',3,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-1042","prompt":"「治安」の読み方として最も適切なものを選びなさい。","options":["ちあん","きょよう","きてん","りじゅん"],"answer":"ちあん","explanationKo":"「治安」는 「ちあん」라고 읽는다. 뜻은 치안이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-22','vocab_question',4,'文字・語彙','{"type":"context_fill","wordKey":"n1-1048","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\nこの装置は従来品を（　）える高精度な測定を可能にした。","options":["還元","比例","崩壊","超"],"answer":"超","explanationKo":"문맥상 「超」가 가장 자연스럽다. 초-; 매우; 한계를 넘는라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-22','vocab_question',5,'文字・語彙','{"type":"context_fill","wordKey":"n1-1050","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n個人情報の（　）については社内規程を厳守してください。","options":["鳥居","負債","取り扱い","脂肪"],"answer":"取り扱い","explanationKo":"문맥상 「取り扱い」가 가장 자연스럽다. 취급; 처리; 취급 방법라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-22','vocab_question',6,'文字・語彙','{"type":"context_fill","wordKey":"n1-1051","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n食器を洗った後、（　）の周りの水気も拭き取った。","options":["議決","流し","水源","戦災"],"answer":"流し","explanationKo":"문맥상 「流し」가 가장 자연스럽다. 싱크대; 개수대라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-22','vocab_question',7,'文字・語彙','{"type":"context_fill","wordKey":"n1-1052","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\nこの制度は地域の課題を住民自身で解決しようとする新しい（　）だ。","options":["試み","志向","換算","奉仕"],"answer":"試み","explanationKo":"문맥상 「試み」가 가장 자연스럽다. 시도; 시험적인 시도라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-22','vocab_question',8,'文字・語彙','{"type":"context_fill","wordKey":"n1-1057","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n新規事業が（　）に乗るまでには予想以上の時間がかかった。","options":["思考","自首","抽選","軌道"],"answer":"軌道","explanationKo":"문맥상 「軌道」가 가장 자연스럽다. 궤도; 정상적인 진행 단계라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-22','vocab_question',9,'文字・語彙','{"type":"context_fill","wordKey":"n1-1067","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\nシステム障害の原因を特定するため、複数の（　）が調査に参加した。","options":["採集","体裁","エンジニア","追跡"],"answer":"エンジニア","explanationKo":"문맥상 「エンジニア」가 가장 자연스럽다. 엔지니어; 기술자라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-22','vocab_question',10,'文字・語彙','{"type":"context_fill","wordKey":"n1-1068","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n利用者が迷わないよう、申請の（　）自体を簡単にする必要がある。","options":["繊維","仕組み","見地","採算"],"answer":"仕組み","explanationKo":"문맥상 「仕組み」가 가장 자연스럽다. 구조; 작동 원리; 체계라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-22','vocab_question',11,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-1044","prompt":"「手段・方法を表す文語的な語。また『本日をもって』のように時点・区切りを示す。」という意味に最も近い語を選びなさい。","options":["以て","磁気","負担","廃棄"],"answer":"以て","explanationKo":"「以て」의 핵심 의미는 ~로써; ~을 가지고; ~을 기하여이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-22','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-1070","prompt":"「国の行政機関で政策の立案・実施などを担う上級公務員。」という意味に最も近い語を選びなさい。","options":["原点","腕前","満場","官僚"],"answer":"官僚","explanationKo":"「官僚」의 핵심 의미는 관료이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-22','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-1072","prompt":"「商品・サービスの交換や価値の尺度として社会で使われる金銭。」という意味に最も近い語を選びなさい。","options":["集計","採決","貨幣","日取り"],"answer":"貨幣","explanationKo":"「貨幣」의 핵심 의미는 화폐이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-22','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-1075","prompt":"「職業上の経験・経歴。また文脈により、通信事業者・運搬体・病原体の保有者などを指す。」という意味に最も近い語を選びなさい。","options":["没収","キャリア","着工","分散"],"answer":"キャリア","explanationKo":"「キャリア」의 핵심 의미는 경력; 직업 경로; 운반체·보균자이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-22','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-1077","prompt":"「学んだ知識・方法を実際の問題・訓練で繰り返し実践すること。」という意味に最も近い語を選びなさい。","options":["演習","歩み","手際","海流"],"answer":"演習","explanationKo":"「演習」의 핵심 의미는 연습; 실습; 훈련이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-22','grammar',1,'〜極まる','{"pattern":"〜極まる","meaningKo":"극히 〜하다","explanation":"〜極まる는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"このような対応は失礼極まる。","ko":"문맥에서 극히 〜하다의 의미로 쓰였다."},{"ja":"安全を軽視するとは、危険極まる行為だ。","ko":"이 문장도 극히 〜하다의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-22','grammar',2,'〜ごとき','{"pattern":"〜ごとき","meaningKo":"〜같은; 〜따위","explanation":"〜ごとき는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"私ごとき者に重要な役目が務まるでしょうか。","ko":"문맥에서 〜같은; 〜따위의 의미로 쓰였다."},{"ja":"一度の失敗ごときで、目標を諦めてはいけない。","ko":"이 문장도 〜같은; 〜따위의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-22','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\nこのような対応は失礼（　）。","options":["〜ようと","〜極まる","〜そびれる","〜ときたら"],"answer":"〜極まる","explanationKo":"문맥상 극히 〜하다를 나타내는 「〜極まる」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-22','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n私（　）者に重要な役目が務まるでしょうか。","options":["〜ごとき","〜たるもの","〜ともなると","〜得る"],"answer":"〜ごとき","explanationKo":"문맥상 〜같은; 〜따위를 나타내는 「〜ごとき」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-22','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n連絡を忘れたばかりに、相手を待たせる（　）。","options":["〜たとたん","〜ないまでも","〜かたがた","〜始末だ"],"answer":"〜始末だ","explanationKo":"문맥상 결국 〜한 지경이다를 나타내는 「〜始末だ」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-22','reading',1,'地域への説明','{"passage":"地域に計画を説明することには、懸念や知識を計画に反映できることという利点がある。しかし、利点だけを見て進めると、形式的な説明だけで終わること。そのため、実施する側は何を目的にするのかを共有し、途中で生じた問題も記録する必要がある。重要なのは、最初の方法を守り続けることではなく、状況を確かめながら質問への回答を次の判断に結びつけることことである。","questions":[{"prompt":"「地域への説明」で筆者が最も重視していることは何か。","options":["質問への回答を次の判断に結びつけること","最初の方法を変更しないこと","速度だけを優先すること","問題を記録しないこと"],"answer":"質問への回答を次の判断に結びつけること","explanationKo":"본문에서는 상황을 확인하면서 質問への回答を次の判断に結びつけること 것이 중요하다고 설명한다."},{"prompt":"本文で注意すべき点として挙げられているものは何か。","options":["形式的な説明だけで終わること","利点が必ずなくなること","説明が不要になること","利用者が減ること"],"answer":"形式的な説明だけで終わること","explanationKo":"장점만 보고 진행하면 形式的な説明だけで終わること 수 있다고 지적한다."},{"prompt":"本文の内容と合うものはどれか。","options":["懸念や知識を計画に反映できること","目的を共有する必要はない","途中の問題は隠すべきだ","判断は最初に一度だけ行うべきだ"],"answer":"懸念や知識を計画に反映できること","explanationKo":"地域に計画を説明すること에는 懸念や知識を計画に反映できること라는 장점이 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-23','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-1103","prompt":"「訴え」の読み方として最も適切なものを選びなさい。","options":["きよ","ひけつ","かくしん","うったえ"],"answer":"うったえ","explanationKo":"「訴え」는 「うったえ」라고 읽는다. 뜻은 호소; 소송상의 주장이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-23','vocab_question',2,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-1106","prompt":"「繊維」の読み方として最も適切なものを選びなさい。","options":["しんこく","さいたく","せんい","しんこう"],"answer":"せんい","explanationKo":"「繊維」는 「せんい」라고 읽는다. 뜻은 섬유이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-23','vocab_question',3,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-1107","prompt":"「思考」の読み方として最も適切なものを選びなさい。","options":["とうぎ","しこう","どひょう","りんぎょう"],"answer":"しこう","explanationKo":"「思考」는 「しこう」라고 읽는다. 뜻은 사고; 생각함이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-23','vocab_question',4,'文字・語彙','{"type":"context_fill","wordKey":"n1-1113","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n（　）年齢の変更に伴い、契約に関する教育の重要性が増した。","options":["成年","起点","利潤","繊維"],"answer":"成年","explanationKo":"문맥상 「成年」가 가장 자연스럽다. 성년; 법적으로 성인이 된 상태라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-23','vocab_question',5,'文字・語彙','{"type":"context_fill","wordKey":"n1-1118","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n制度の（　）を理解せずに手続きだけを変えても効果は薄い。","options":["キャリア","過労","懸賞","趣旨"],"answer":"趣旨","explanationKo":"문맥상 「趣旨」가 가장 자연스럽다. 취지; 주된 목적과 뜻라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-23','vocab_question',6,'文字・語彙','{"type":"context_fill","wordKey":"n1-1131","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n子どもの（　）を減らすには教育と生活の両面から支援が必要だ。","options":["負債","漁船","貧困","鳥居"],"answer":"貧困","explanationKo":"문맥상 「貧困」가 가장 자연스럽다. 빈곤라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-23','vocab_question',7,'文字・語彙','{"type":"context_fill","wordKey":"n1-1132","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n事故を減らすため、危険運転の（　）が強化された。","options":["負担","取り締まり","戦災","議決"],"answer":"取り締まり","explanationKo":"문맥상 「取り締まり」가 가장 자연스럽다. 단속; 규제 집행라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-23','vocab_question',8,'文字・語彙','{"type":"context_fill","wordKey":"n1-1135","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n広告収入が増え、事業全体の（　）も改善した。","options":["収益","換算","奉仕","質疑"],"answer":"収益","explanationKo":"문맥상 「収益」가 가장 자연스럽다. 수익; 사업에서 얻는 이익라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-23','vocab_question',9,'文字・語彙','{"type":"context_fill","wordKey":"n1-1143","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n自治体は観光（　）のため、地域資源を生かした企画を進めている。","options":["願書","手引き","改定","振興"],"answer":"振興","explanationKo":"문맥상 「振興」가 가장 자연스럽다. 진흥; 발전을 촉진함라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-23','vocab_question',10,'文字・語彙','{"type":"context_fill","wordKey":"n1-1147","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n新人にはまず先輩の対応を（　）にしてもらう。","options":["体裁","背景","手本","採集"],"answer":"手本","explanationKo":"문맥상 「手本」가 가장 자연스럽다. 본보기; 모범; 견본라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-23','vocab_question',11,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-1149","prompt":"「一か所に集中しているものを複数の場所・対象に分けること。また、分かれて散ること。」という意味に最も近い語を選びなさい。","options":["免除","分散","降伏","崇拝"],"answer":"分散","explanationKo":"「分散」의 핵심 의미는 분산; 흩어짐이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-23','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-1157","prompt":"「住むこと、住居に関すること。特に『衣食住』などで生活の住居面を表す。」という意味に最も近い語を選びなさい。","options":["住","国産","間柄","見合い"],"answer":"住","explanationKo":"「住」의 핵심 의미는 주거; 생활하는 곳이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-23','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-1160","prompt":"「神仏などに願いを伝えること。また、物事が望ましい結果になるよう強く願う気持ち。」という意味に最も近い語を選びなさい。","options":["腕前","満場","変遷","祈り"],"answer":"祈り","explanationKo":"「祈り」의 핵심 의미는 기도; 바람이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-23','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-1165","prompt":"「スポーツ・芸術などを職業としてではなく趣味として行う人。」という意味に最も近い語を選びなさい。","options":["採決","白状","アマチュア","集計"],"answer":"アマチュア","explanationKo":"「アマチュア」의 핵심 의미는 아마추어; 비전문가이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-23','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-1166","prompt":"「自分の利益を優先せず、他人・社会・組織などのために力を尽くすこと。」という意味に最も近い語を選びなさい。","options":["鉱業","奉仕","階層","冠"],"answer":"奉仕","explanationKo":"「奉仕」의 핵심 의미는 봉사; 헌신이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-23','grammar',1,'〜始末だ','{"pattern":"〜始末だ","meaningKo":"결국 〜한 지경이다","explanation":"〜始末だ는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"準備を怠った結果、締切に間に合わない始末だ。","ko":"문맥에서 결국 〜한 지경이다의 의미로 쓰였다."},{"ja":"連絡を忘れたばかりに、相手を待たせる始末になった。","ko":"이 문장도 결국 〜한 지경이다의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-23','grammar',2,'〜ずくめ','{"pattern":"〜ずくめ","meaningKo":"온통 〜뿐","explanation":"〜ずくめ는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"今日は朝から良い知らせずくめだった。","ko":"문맥에서 온통 〜뿐의 의미로 쓰였다."},{"ja":"旅行中は予想外の出来事ずくめで、忘れられない思い出になった。","ko":"이 문장도 온통 〜뿐의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-23','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n準備を怠った結果、締切に間に合わない（　）。","options":["〜始末だ","〜たとたん","〜ないまでも","〜かたがた"],"answer":"〜始末だ","explanationKo":"문맥상 결국 〜한 지경이다를 나타내는 「〜始末だ」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-23','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n今日は朝から良い知らせ（　）だった。","options":["〜つつある","〜あまり","〜限りだ","〜ずくめ"],"answer":"〜ずくめ","explanationKo":"문맥상 온통 〜뿐를 나타내는 「〜ずくめ」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-23','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n基本的な用語（　）理解していない。","options":["〜あって","〜かねない","〜すら","〜てしかるべき"],"answer":"〜すら","explanationKo":"문맥상 〜조차를 나타내는 「〜すら」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-23','reading',1,'学習の記録を使う','{"passage":"学習の記録を残すことには、理解の変化を振り返れることという利点がある。しかし、利点だけを見て進めると、回数だけを競うこと。そのため、実施する側は何を目的にするのかを共有し、途中で生じた問題も記録する必要がある。重要なのは、最初の方法を守り続けることではなく、状況を確かめながらつまずいた理由を次の学習に生かすことことである。","questions":[{"prompt":"「学習の記録を使う」で筆者が最も重視していることは何か。","options":["つまずいた理由を次の学習に生かすこと","最初の方法を変更しないこと","速度だけを優先すること","問題を記録しないこと"],"answer":"つまずいた理由を次の学習に生かすこと","explanationKo":"본문에서는 상황을 확인하면서 つまずいた理由を次の学習に生かすこと 것이 중요하다고 설명한다."},{"prompt":"本文で注意すべき点として挙げられているものは何か。","options":["回数だけを競うこと","利点が必ずなくなること","説明が不要になること","利用者が減ること"],"answer":"回数だけを競うこと","explanationKo":"장점만 보고 진행하면 回数だけを競うこと 수 있다고 지적한다."},{"prompt":"本文の内容と合うものはどれか。","options":["理解の変化を振り返れること","目的を共有する必要はない","途中の問題は隠すべきだ","判断は最初に一度だけ行うべきだ"],"answer":"理解の変化を振り返れること","explanationKo":"学習の記録を残すこと에는 理解の変化を振り返れること라는 장점이 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-24','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-1195","prompt":"「脂肪」の読み方として最も適切なものを選びなさい。","options":["しぼう","かいうん","はんきょう","ほうかい"],"answer":"しぼう","explanationKo":"「脂肪」는 「しぼう」라고 읽는다. 뜻은 지방이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
