INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-24','vocab_question',10,'文字・語彙','{"type":"context_fill","wordKey":"n1-1239","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n両国の（　）は会談で経済協力について意見を交わした。","options":["抽選","不意","鉄鋼","首脳"],"answer":"首脳","explanationKo":"문맥상 「首脳」가 가장 자연스럽다. 수뇌; 최고 지도자라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-24','vocab_question',11,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-1240","prompt":"「新しい勢力・企業・産業・国などが現れ、発展してくること。」という意味に最も近い語を選びなさい。","options":["背景","趣旨","新興","体裁"],"answer":"新興","explanationKo":"「新興」의 핵심 의미는 신흥; 새롭게 생겨 세력을 얻음이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-24','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-1243","prompt":"「社会的地位・所得・役割などによって分けられた層。また、構造上の上下関係を持つ段階。」という意味に最も近い語を選びなさい。","options":["願書","階層","訴え","威力"],"answer":"階層","explanationKo":"「階層」의 핵심 의미는 계층; 층위이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-24','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-1251","prompt":"「神・宗教的対象、または人物などを非常に尊いものとして敬い仰ぐこと。」という意味に最も近い語を選びなさい。","options":["崇拝","模倣","外貨","境遇"],"answer":"崇拝","explanationKo":"「崇拝」의 핵심 의미는 숭배; 경배이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-24','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-1252","prompt":"「本来その人が判断すべき事柄に外部から口や手を出し、影響を与えること。」という意味に最も近い語を選びなさい。","options":["器官","試み","祈り","干渉"],"answer":"干渉","explanationKo":"「干渉」의 핵심 의미는 간섭이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-24','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-1253","prompt":"「武力などによって国・地域・相手を支配下に置くこと。また比喩的に困難を克服すること。」という意味に最も近い語を選びなさい。","options":["良心","有様","征服","収益"],"answer":"征服","explanationKo":"「征服」의 핵심 의미는 정복이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-24','grammar',1,'〜すら','{"pattern":"〜すら","meaningKo":"〜조차","explanation":"〜すら는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"忙しくて昼食を取る時間すらなかった。","ko":"문맥에서 〜조차의 의미로 쓰였다."},{"ja":"基本的な用語すら理解していない。","ko":"이 문장도 〜조차의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-24','grammar',2,'〜そびれる','{"pattern":"〜そびれる","meaningKo":"〜할 기회를 놓치다","explanation":"〜そびれる는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"質問したいことがあったが、聞きそびれてしまった。","ko":"문맥에서 〜할 기회를 놓치다의 의미로 쓰였다."},{"ja":"混雑していて、昼食を食べそびれた。","ko":"이 문장도 〜할 기회를 놓치다의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-24','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n忙しくて昼食を取る時間（　）なかった。","options":["〜てしかるべき","〜あって","〜かねない","〜すら"],"answer":"〜すら","explanationKo":"문맥상 〜조차를 나타내는 「〜すら」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-24','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n質問したいことがあったが、聞き（　）しまった。","options":["〜いかんだ","〜かねる","〜そびれる","〜ではあるまいし"],"answer":"〜そびれる","explanationKo":"문맥상 〜할 기회를 놓치다를 나타내는 「〜そびれる」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-24','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n専門家（　）、根拠を明確に説明すべきだ。","options":["〜が早いか","〜たるもの","〜ときたら","〜以上は"],"answer":"〜たるもの","explanationKo":"문맥상 〜인 이상를 나타내는 「〜たるもの」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-24','reading',1,'判断を急がない場面','{"passage":"結論を急がないことには、不足している情報を確かめられることという利点がある。しかし、利点だけを見て進めると、判断を先延ばしにするだけになること。そのため、実施する側は何を目的にするのかを共有し、途中で生じた問題も記録する必要がある。重要なのは、最初の方法を守り続けることではなく、状況を確かめながら期限と追加で調べる事項を明確にすることことである。","questions":[{"prompt":"「判断を急がない場面」で筆者が最も重視していることは何か。","options":["期限と追加で調べる事項を明確にすること","最初の方法を変更しないこと","速度だけを優先すること","問題を記録しないこと"],"answer":"期限と追加で調べる事項を明確にすること","explanationKo":"본문에서는 상황을 확인하면서 期限と追加で調べる事項を明確にすること 것이 중요하다고 설명한다."},{"prompt":"本文で注意すべき点として挙げられているものは何か。","options":["判断を先延ばしにするだけになること","利点が必ずなくなること","説明が不要になること","利用者が減ること"],"answer":"判断を先延ばしにするだけになること","explanationKo":"장점만 보고 진행하면 判断を先延ばしにするだけになること 수 있다고 지적한다."},{"prompt":"本文の内容と合うものはどれか。","options":["不足している情報を確かめられること","目的を共有する必要はない","途中の問題は隠すべきだ","判断は最初に一度だけ行うべきだ"],"answer":"不足している情報を確かめられること","explanationKo":"結論を急がないこと에는 不足している情報を確かめられること라는 장점이 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-25','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-1280","prompt":"「細胞」の読み方として最も適切なものを選びなさい。","options":["かんげん","さいぼう","ないらん","てんさい"],"answer":"さいぼう","explanationKo":"「細胞」는 「さいぼう」라고 읽는다. 뜻은 세포이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
