INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-25','vocab_question',3,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-1291","prompt":"「自首」の読み方として最も適切なものを選びなさい。","options":["もけい","さいきん","ごく","じしゅ"],"answer":"じしゅ","explanationKo":"「自首」는 「じしゅ」라고 읽는다. 뜻은 자수이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-25','vocab_question',4,'文字・語彙','{"type":"context_fill","wordKey":"n1-1292","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n所得税は期限内に正しく（　）する必要がある。","options":["除外","就業","申告","刑罰"],"answer":"申告","explanationKo":"문맥상 「申告」가 가장 자연스럽다. 신고; 신고함라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
