INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-25','vocab_question',7,'文字・語彙','{"type":"context_fill","wordKey":"n1-1298","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n説明の後に十分な（　）の時間を設けた。","options":["迫害","学説","長編","質疑"],"answer":"質疑","explanationKo":"문맥상 「質疑」가 가장 자연스럽다. 질의; 질문과 답변라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-25','vocab_question',8,'文字・語彙','{"type":"context_fill","wordKey":"n1-1302","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n日程変更について参加者全員の（　）を得た。","options":["軌道","アマチュア","了承","公用"],"answer":"了承","explanationKo":"문맥상 「了承」가 가장 자연스럽다. 양해; 승낙; 이해하고 받아들임라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-25','vocab_question',9,'文字・語彙','{"type":"context_fill","wordKey":"n1-1303","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n長年続いた協力関係の（　）として記念品が贈られた。","options":["私有","証","負担","滅亡"],"answer":"証","explanationKo":"문맥상 「証」가 가장 자연스럽다. 증거; 증표; 증명라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-25','vocab_question',10,'文字・語彙','{"type":"context_fill","wordKey":"n1-1305","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n大雨に備えて河川周辺の（　）工事が進められている。","options":["土木","質疑","腐敗","語源"],"answer":"土木","explanationKo":"문맥상 「土木」가 가장 자연스럽다. 토목; 토목 공사라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
