INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-25','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-1309","prompt":"「要素を一定の順序・規則に従って並べること。また、その並び。」という意味に最も近い語を選びなさい。","options":["征服","追跡","配列","廃棄"],"answer":"配列","explanationKo":"「配列」의 핵심 의미는 배열; 일정한 순서로 배치함이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
