INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-25','grammar',1,'〜たるもの','{"pattern":"〜たるもの","meaningKo":"〜인 이상","explanation":"〜たるもの는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"指導者たるもの、冷静な判断を示さなければならない。","ko":"문맥에서 〜인 이상의 의미로 쓰였다."},{"ja":"専門家たるもの、根拠を明確に説明すべきだ。","ko":"이 문장도 〜인 이상의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-25','grammar',2,'〜たとたん','{"pattern":"〜たとたん","meaningKo":"〜하자마자","explanation":"〜たとたん는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"窓を開けたとたん、強い風が吹き込んできた。","ko":"문맥에서 〜하자마자의 의미로 쓰였다."},{"ja":"発表が終わったとたん、会場から質問が相次いだ。","ko":"이 문장도 〜하자마자의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-25','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n指導者（　）、冷静な判断を示さなければならない。","options":["〜以上は","〜が早いか","〜たるもの","〜ときたら"],"answer":"〜たるもの","explanationKo":"문맥상 〜인 이상를 나타내는 「〜たるもの」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-25','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n窓を開け（　）、強い風が吹き込んできた。","options":["〜からある","〜たとたん","〜ともなると","〜ようが"],"answer":"〜たとたん","explanationKo":"문맥상 〜하자마자를 나타내는 「〜たとたん」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-25','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n技術の進歩によって、働き方も変化し（　）。","options":["〜つつある","〜ないまでも","〜ようと","〜きらいがある"],"answer":"〜つつある","explanationKo":"문맥상 점차 〜하고 있다를 나타내는 「〜つつある」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-25','reading',1,'共有資源の守り方','{"passage":"共有の資源を利用することには、多くの人が便益を得られることという利点がある。しかし、利点だけを見て進めると、一部の利用が負担を他者に移すこと。そのため、実施する側は何を目的にするのかを共有し、途中で生じた問題も記録する必要がある。重要なのは、最初の方法を守り続けることではなく、状況を確かめながら利用の条件を互いに見直すことことである。","questions":[{"prompt":"「共有資源の守り方」で筆者が最も重視していることは何か。","options":["利用の条件を互いに見直すこと","最初の方法を変更しないこと","速度だけを優先すること","問題を記録しないこと"],"answer":"利用の条件を互いに見直すこと","explanationKo":"본문에서는 상황을 확인하면서 利用の条件を互いに見直すこと 것이 중요하다고 설명한다."},{"prompt":"本文で注意すべき点として挙げられているものは何か。","options":["一部の利用が負担を他者に移すこと","利点が必ずなくなること","説明が不要になること","利用者が減ること"],"answer":"一部の利用が負担を他者に移すこと","explanationKo":"장점만 보고 진행하면 一部の利用が負担を他者に移すこと 수 있다고 지적한다."},{"prompt":"本文の内容と合うものはどれか。","options":["多くの人が便益を得られること","目的を共有する必要はない","途中の問題は隠すべきだ","判断は最初に一度だけ行うべきだ"],"answer":"多くの人が便益を得られること","explanationKo":"共有の資源を利用すること에는 多くの人が便益を得られること라는 장점이 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-26','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-1362","prompt":"「志望」の読み方として最も適切なものを選びなさい。","options":["みつど","しょひょう","しぼう","ぶんぎょう"],"answer":"しぼう","explanationKo":"「志望」는 「しぼう」라고 읽는다. 뜻은 지망; 희망함이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-26','vocab_question',2,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-1367","prompt":"「懸賞」の読み方として最も適切なものを選びなさい。","options":["もって","けんしょう","てんさい","かんげん"],"answer":"けんしょう","explanationKo":"「懸賞」는 「けんしょう」라고 읽는다. 뜻은 현상; 상금·상품을 건 공모이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-26','vocab_question',3,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-1368","prompt":"「歩み」の読み方として最も適切なものを選びなさい。","options":["あゆみ","ほうかい","はんえい","じたい"],"answer":"あゆみ","explanationKo":"「歩み」는 「あゆみ」라고 읽는다. 뜻은 걸음; 행보; 과정이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-26','vocab_question',4,'文字・語彙','{"type":"context_fill","wordKey":"n1-1374","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n一定の条件を満たす学生は受験料が（　）される。","options":["細菌","語句","運搬","免除"],"answer":"免除","explanationKo":"문맥상 「免除」가 가장 자연스럽다. 면제라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-26','vocab_question',5,'文字・語彙','{"type":"context_fill","wordKey":"n1-1381","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n旅行資金を貯めるため、しばらく外食を控えて（　）している。","options":["就業","思考","倹約","除外"],"answer":"倹約","explanationKo":"문맥상 「倹約」가 가장 자연스럽다. 검약; 절약라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-26','vocab_question',6,'文字・語彙','{"type":"context_fill","wordKey":"n1-1382","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n社外秘の資料は権限を持つ社員だけが（　）できる。","options":["貯蓄","閲覧","アプローチ","捜索"],"answer":"閲覧","explanationKo":"문맥상 「閲覧」가 가장 자연스럽다. 열람라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-26','vocab_question',7,'文字・語彙','{"type":"context_fill","wordKey":"n1-1388","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n配送番号を入力すると荷物の現在地を（　）できる。","options":["追跡","免除","許容","起点"],"answer":"追跡","explanationKo":"문맥상 「追跡」가 가장 자연스럽다. 추적라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-26','vocab_question',8,'文字・語彙','{"type":"context_fill","wordKey":"n1-1390","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n入学（　）は締切日までに郵送しなければならない。","options":["土俵","林業","討議","願書"],"answer":"願書","explanationKo":"문맥상 「願書」가 가장 자연스럽다. 원서; 지원서라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-26','vocab_question',9,'文字・語彙','{"type":"context_fill","wordKey":"n1-1391","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n毎月一定額を（　）するため、自動積立を設定した。","options":["アマチュア","土木","貯蓄","軌道"],"answer":"貯蓄","explanationKo":"문맥상 「貯蓄」가 가장 자연스럽다. 저축; 축적라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-26','vocab_question',10,'文字・語彙','{"type":"context_fill","wordKey":"n1-1393","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n製品は品質検査の結果に応じて複数の（　）に分類される。","options":["模索","等級","滅亡","私有"],"answer":"等級","explanationKo":"문맥상 「等級」가 가장 자연스럽다. 등급; 급수라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-26','vocab_question',11,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-1401","prompt":"「地位・栄誉を象徴する冠。また、『三冠』など、優勝・称号を数える語の一部として用いる。」という意味に最も近い語を選びなさい。","options":["冠","腐敗","語源","磁気"],"answer":"冠","explanationKo":"「冠」의 핵심 의미는 관; 왕관; 우승·칭호를 나타내는 관이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-26','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-1402","prompt":"「土地・分野などがまだ十分に開発・開拓されていないこと。歴史的には文明発達の程度を表す語としても使われた。」という意味に最も近い語を選びなさい。","options":["鉄鋼","治安","収益","未開"],"answer":"未開","explanationKo":"「未開」의 핵심 의미는 미개척; 아직 개발·개척되지 않음이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-26','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-1404","prompt":"「公的機関・組織などが、相手に一定の行動を取るよう正式にすすめること。」という意味に最も近い語を選びなさい。","options":["閲覧","採集","勧告","征服"],"answer":"勧告","explanationKo":"「勧告」의 핵심 의미는 권고; 공식적으로 조치를 권함이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-26','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-1406","prompt":"「非常に小さな単細胞の微生物の一群。病気・発酵・分解などに関わるものがある。」という意味に最も近い語を選びなさい。","options":["改定","細菌","歩み","手引き"],"answer":"細菌","explanationKo":"「細菌」의 핵심 의미는 세균; 박테리아이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-26','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-1410","prompt":"「応募者・候補などの中から、くじや乱数などによって公平に選ぶこと。」という意味に最も近い語を選びなさい。","options":["抽選","境遇","仕組み","アンケート"],"answer":"抽選","explanationKo":"「抽選」의 핵심 의미는 추첨; 제비뽑기이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-26','grammar',1,'〜つつある','{"pattern":"〜つつある","meaningKo":"점차 〜하고 있다","explanation":"〜つつある는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"社会の価値観は少しずつ変わりつつある。","ko":"문맥에서 점차 〜하고 있다의 의미로 쓰였다."},{"ja":"技術の進歩によって、働き方も変化しつつある。","ko":"이 문장도 점차 〜하고 있다의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-26','grammar',2,'〜てしかるべき','{"pattern":"〜てしかるべき","meaningKo":"당연히 〜해야 한다","explanation":"〜てしかるべき는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"重要な変更は、事前に説明されてしかるべきだ。","ko":"문맥에서 당연히 〜해야 한다의 의미로 쓰였다."},{"ja":"努力した人が評価されてしかるべきだ。","ko":"이 문장도 당연히 〜해야 한다의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
