INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-26','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n重要な変更は、事前に説明され（　）だ。","options":["〜てしかるべき","〜あまり","〜得る","〜極まる"],"answer":"〜てしかるべき","explanationKo":"문맥상 당연히 〜해야 한다를 나타내는 「〜てしかるべき」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
