INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-26','reading',1,'新しい道具の導入','{"passage":"新しい道具を導入することには、従来の作業を補助できることという利点がある。しかし、利点だけを見て進めると、目的を忘れて導入自体が目標になること。そのため、実施する側は何を目的にするのかを共有し、途中で生じた問題も記録する必要がある。重要なのは、最初の方法を守り続けることではなく、状況を確かめながら利用者の課題から効果を確かめることことである。","questions":[{"prompt":"「新しい道具の導入」で筆者が最も重視していることは何か。","options":["利用者の課題から効果を確かめること","最初の方法を変更しないこと","速度だけを優先すること","問題を記録しないこと"],"answer":"利用者の課題から効果を確かめること","explanationKo":"본문에서는 상황을 확인하면서 利用者の課題から効果を確かめること 것이 중요하다고 설명한다."},{"prompt":"本文で注意すべき点として挙げられているものは何か。","options":["目的を忘れて導入自体が目標になること","利点が必ずなくなること","説明が不要になること","利用者が減ること"],"answer":"目的を忘れて導入自体が目標になること","explanationKo":"장점만 보고 진행하면 目的を忘れて導入自体が目標になること 수 있다고 지적한다."},{"prompt":"本文の内容と合うものはどれか。","options":["従来の作業を補助できること","目的を共有する必要はない","途中の問題は隠すべきだ","判断は最初に一度だけ行うべきだ"],"answer":"従来の作業を補助できること","explanationKo":"新しい道具を導入すること에는 従来の作業を補助できること라는 장점이 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
