INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-27','vocab_question',6,'文字・語彙','{"type":"context_fill","wordKey":"n1-1453","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n医師の勧めで数日間温泉地に滞在し、（　）することにした。","options":["思考","自首","保養","就業"],"answer":"保養","explanationKo":"문맥상 「保養」가 가장 자연스럽다. 보양; 요양; 휴양라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-27','vocab_question',7,'文字・語彙','{"type":"context_fill","wordKey":"n1-1455","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n料理人は鮮やかな包丁さばきで見事な（　）を披露した。","options":["未開","腕前","貧困","アラブ"],"answer":"腕前","explanationKo":"문맥상 「腕前」가 가장 자연스럽다. 솜씨; 실력; 기량라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-27','vocab_question',8,'文字・語彙','{"type":"context_fill","wordKey":"n1-1458","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n事業拡大のために借入金が増え、会社の（　）も大きくなった。","options":["負債","願書","刑罰","除外"],"answer":"負債","explanationKo":"문맥상 「負債」가 가장 자연스럽다. 부채; 갚아야 할 채무라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-27','vocab_question',9,'文字・語彙','{"type":"context_fill","wordKey":"n1-1461","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n会社は新しい収益モデルを（　）している。","options":["長編","官僚","脂肪","模索"],"answer":"模索","explanationKo":"문맥상 「模索」가 가장 자연스럽다. 모색; 해결책을 찾아봄라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-27','vocab_question',10,'文字・語彙','{"type":"context_fill","wordKey":"n1-1472","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n長期化した（　）によって、多くの住民が国外へ避難した。","options":["絶望","麻痺","内乱","訴訟"],"answer":"内乱","explanationKo":"문맥상 「内乱」가 가장 자연스럽다. 내란; 국내의 무력 충돌라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-27','vocab_question',11,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-1480","prompt":"「結婚相手を探す目的で、第三者の紹介によって男女が会うこと。」という意味に最も近い語を選びなさい。","options":["様相","見合い","私有","模索"],"answer":"見合い","explanationKo":"「見合い」의 핵심 의미는 맞선; 중매를 통한 만남이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-27','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-1483","prompt":"「相撲を取る円形の競技場。また比喩的に、競争・議論・活動が行われる場。」という意味に最も近い語を選びなさい。","options":["土俵","語源","磁気","試み"],"answer":"土俵","explanationKo":"「土俵」의 핵심 의미는 도효; 스모 경기장; 비유적으로 활동 무대이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-27','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-1486","prompt":"「仕事・作業を処理する方法や、その進め方の上手さ。」という意味に最も近い語を選びなさい。","options":["治安","収益","良心","手際"],"answer":"手際","explanationKo":"「手際」의 핵심 의미는 솜씨; 일처리 능숙함이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-27','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-1498","prompt":"「方法・手順・方向などを教えて案内すること。また、そのための説明書・案内書。」という意味に最も近い語を選びなさい。","options":["冠","付録","手引き","階層"],"answer":"手引き","explanationKo":"「手引き」의 핵심 의미는 안내; 지침; 안내서이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-27','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-1499","prompt":"「複数のものを同じ段階・位置関係で並べること。コンピュータでは複数の処理を同時に進める意味でも使う。」という意味に最も近い語を選びなさい。","options":["キャリア","並列","見地","採算"],"answer":"並列","explanationKo":"「並列」의 핵심 의미는 병렬; 나란히 배치함이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-27','grammar',1,'〜ではあるまいし','{"pattern":"〜ではあるまいし","meaningKo":"〜도 아닌데","explanation":"〜ではあるまいし는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"子どもではあるまいし、感情だけで決めるべきではない。","ko":"문맥에서 〜도 아닌데의 의미로 쓰였다."},{"ja":"初めてではあるまいし、手順を確認してから始めよう。","ko":"이 문장도 〜도 아닌데의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-27','grammar',2,'〜ときたら','{"pattern":"〜ときたら","meaningKo":"〜라고 하면; 〜는","explanation":"〜ときたら는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"今年の夏の暑さときたら、とても外出できるものではなかった。","ko":"문맥에서 〜라고 하면; 〜는의 의미로 쓰였다."},{"ja":"彼の記憶力ときたら、誰もが驚くほどだ。","ko":"이 문장도 〜라고 하면; 〜는의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-27','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n子ども（　）、感情だけで決めるべきではない。","options":["〜ではあるまいし","〜あって","〜かたがた","〜ごとき"],"answer":"〜ではあるまいし","explanationKo":"문맥상 〜도 아닌데를 나타내는 「〜ではあるまいし」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-27','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n今年の夏の暑さ（　）、とても外出できるものではなかった。","options":["〜いかんだ","〜限りだ","〜始末だ","〜ときたら"],"answer":"〜ときたら","explanationKo":"문맥상 〜라고 하면; 〜는를 나타내는 「〜ときたら」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-27','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n責任者（　）、幅広い判断力が求められる。","options":["〜かねない","〜ずくめ","〜ともなると","〜以上は"],"answer":"〜ともなると","explanationKo":"문맥상 〜정도가 되면를 나타내는 「〜ともなると」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-27','reading',1,'異なる立場を比べる','{"passage":"異なる立場の意見を比べることには、見落としていた影響に気づけることという利点がある。しかし、利点だけを見て進めると、人数の多い意見だけで決めること。そのため、実施する側は何を目的にするのかを共有し、途中で生じた問題も記録する必要がある。重要なのは、最初の方法を守り続けることではなく、状況を確かめながら各案が負担する条件を整理することことである。","questions":[{"prompt":"「異なる立場を比べる」で筆者が最も重視していることは何か。","options":["各案が負担する条件を整理すること","最初の方法を変更しないこと","速度だけを優先すること","問題を記録しないこと"],"answer":"各案が負担する条件を整理すること","explanationKo":"본문에서는 상황을 확인하면서 各案が負担する条件を整理すること 것이 중요하다고 설명한다."},{"prompt":"本文で注意すべき点として挙げられているものは何か。","options":["人数の多い意見だけで決めること","利点が必ずなくなること","説明が不要になること","利用者が減ること"],"answer":"人数の多い意見だけで決めること","explanationKo":"장점만 보고 진행하면 人数の多い意見だけで決めること 수 있다고 지적한다."},{"prompt":"本文の内容と合うものはどれか。","options":["見落としていた影響に気づけること","目的を共有する必要はない","途中の問題は隠すべきだ","判断は最初に一度だけ行うべきだ"],"answer":"見落としていた影響に気づけること","explanationKo":"異なる立場の意見を比べること에는 見落としていた影響に気づけること라는 장점이 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-28','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-1540","prompt":"「模倣」の読み方として最も適切なものを選びなさい。","options":["もほう","あっぱく","ちょちく","かみ"],"answer":"もほう","explanationKo":"「模倣」는 「もほう」라고 읽는다. 뜻은 모방; 흉내 냄이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
