INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-28','vocab_question',8,'文字・語彙','{"type":"context_fill","wordKey":"n1-1566","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n提案は（　）一致で可決された。","options":["付録","満場","アラブ","未開"],"answer":"満場","explanationKo":"문맥상 「満場」가 가장 자연스럽다. 장내 전체; 참석자 전원라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-28','vocab_question',9,'文字・語彙','{"type":"context_fill","wordKey":"n1-1572","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n早朝、港から多くの（　）が一斉に出港した。","options":["漁船","手引き","除外","就業"],"answer":"漁船","explanationKo":"문맥상 「漁船」가 가장 자연스럽다. 어선; 고기잡이배라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-28','vocab_question',10,'文字・語彙','{"type":"context_fill","wordKey":"n1-1573","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n（　）による損害を完全に防ぐことは難しいが、備えはできる。","options":["討議","演習","干渉","天災"],"answer":"天災","explanationKo":"문맥상 「天災」가 가장 자연스럽다. 천재; 자연재해라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-28','vocab_question',11,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-1574","prompt":"「物理では基準物質に対する密度の比。比喩的には、全体の中で占める重要さ・割合。」という意味に最も近い語を選びなさい。","options":["麻痺","迫害","比重","絶望"],"answer":"比重","explanationKo":"「比重」의 핵심 의미는 비중; 중요도이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-28','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-1576","prompt":"「一つの仕事を複数の人・組織で役割ごとに分けて行うこと。」という意味に最も近い語を選びなさい。","options":["換算","分業","熱意","志向"],"answer":"分業","explanationKo":"「分業」의 핵심 의미는 분업이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-28','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-1577","prompt":"「物質・情報・影響などが広い範囲へ散って広がること。」という意味に最も近い語を選びなさい。","options":["拡散","誇張","分散","没収"],"answer":"拡散","explanationKo":"「拡散」의 핵심 의미는 확산; 퍼짐이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-28','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-1594","prompt":"「森林を育成・管理し、木材などの資源を生産・利用する産業。」という意味に最も近い語を選びなさい。","options":["収益","良心","有様","林業"],"answer":"林業","explanationKo":"「林業」의 핵심 의미는 임업이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-28','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-1597","prompt":"「海水が一定の方向・速度で大規模に流れる現象。」という意味に最も近い語を選びなさい。","options":["鉱業","決算","海流","冠"],"answer":"海流","explanationKo":"「海流」의 핵심 의미는 해류이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-28','grammar',1,'〜ともなると','{"pattern":"〜ともなると","meaningKo":"〜정도가 되면","explanation":"〜ともなると는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"年末ともなると、街は買い物客で混雑する。","ko":"문맥에서 〜정도가 되면의 의미로 쓰였다."},{"ja":"責任者ともなると、幅広い判断力が求められる。","ko":"이 문장도 〜정도가 되면의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-28','grammar',2,'〜ないまでも','{"pattern":"〜ないまでも","meaningKo":"〜까지는 아니더라도","explanation":"〜ないまでも는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"毎日でないまでも、定期的に復習することが大切だ。","ko":"문맥에서 〜까지는 아니더라도의 의미로 쓰였다."},{"ja":"完璧でないまでも、納得できる案をまとめたい。","ko":"이 문장도 〜까지는 아니더라도의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-28','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n年末（　）、街は買い物客で混雑する。","options":["〜以上は","〜かねない","〜ずくめ","〜ともなると"],"answer":"〜ともなると","explanationKo":"문맥상 〜정도가 되면를 나타내는 「〜ともなると」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-28','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n毎日で（　）、定期的に復習することが大切だ。","options":["〜かねる","〜すら","〜ないまでも","〜ようが"],"answer":"〜ないまでも","explanationKo":"문맥상 〜까지는 아니더라도를 나타내는 「〜ないまでも」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-28','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n緊張の（　）、質問にうまく答えられなかった。","options":["〜そびれる","〜あまり","〜ようと","〜が早いか"],"answer":"〜あまり","explanationKo":"문맥상 너무 〜한 나머지를 나타내는 「〜あまり」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-10-28','reading',1,'改善を続ける仕組み','{"passage":"改善を継続することには、小さな問題を大きくなる前に直せることという利点がある。しかし、利点だけを見て進めると、変更が多すぎて現場が混乱すること。そのため、実施する側は何を目的にするのかを共有し、途中で生じた問題も記録する必要がある。重要なのは、最初の方法を守り続けることではなく、状況を確かめながら目的と効果を確かめながら進めることことである。","questions":[{"prompt":"「改善を続ける仕組み」で筆者が最も重視していることは何か。","options":["目的と効果を確かめながら進めること","最初の方法を変更しないこと","速度だけを優先すること","問題を記録しないこと"],"answer":"目的と効果を確かめながら進めること","explanationKo":"본문에서는 상황을 확인하면서 目的と効果を確かめながら進めること 것이 중요하다고 설명한다."},{"prompt":"本文で注意すべき点として挙げられているものは何か。","options":["変更が多すぎて現場が混乱すること","利点が必ずなくなること","説明が不要になること","利用者が減ること"],"answer":"変更が多すぎて現場が混乱すること","explanationKo":"장점만 보고 진행하면 変更が多すぎて現場が混乱すること 수 있다고 지적한다."},{"prompt":"本文の内容と合うものはどれか。","options":["小さな問題を大きくなる前に直せること","目的を共有する必要はない","途中の問題は隠すべきだ","判断は最初に一度だけ行うべきだ"],"answer":"小さな問題を大きくなる前に直せること","explanationKo":"改善を継続すること에는 小さな問題を大きくなる前に直せること라는 장점이 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
